                                    continue;
                                }
                                if (bytesPerImage == 0) {
                                    NSLog(@"MGL SECURITY ERROR: Invalid bytesPerImage (0) passed to Metal replaceRegion (level %d, face %d) - SKIPPING to prevent crash", level, face);
                                    continue;
                                }
                                if (hasExplicitDataSize) {
                                    BOOL uploaded = [self uploadTextureSliceViaBlit:texture
                                                                           texName:tex->name
                                                                        texTarget:tex->target
                                                                             bytes:srcData
                                                                       bytesPerRow:bytesPerRow
                                                                     bytesPerImage:bytesPerImage
                                                                             width:width
                                                                            height:height
                                                                             depth:1
                                                                             level:level
                                                                             slice:face];
                                    if (!uploaded) {
                                        NSLog(@"MGL WARNING: 2D direct blit upload failed (level %d, face %d)", level, face);
                                    }
                                } else {
                                    NSLog(@"MGL INFO: Skipping 2D upload with synthesized data size (level %d, face %d)", level, face);
                                }
                            }
                            free(swizzledUploadData);
                            free(expandedUploadData);
                        } else {
                            NSLog(@"MGL WARNING: Skipping 2D texture upload due to invalid data or parameters");
                        }
                    }
                }
            }
        }
    }
    else
    {
        if (hasUploadableCPUData) {
            NSLog(@"MGL INFO: Re-uploading existing CPU texture data (tex=%d, dims=%lux%lu)",
                  tex->name, (unsigned long)texture.width, (unsigned long)texture.height);

            for (int face = 0; face < num_faces; face++) {
                for (int level = 0; level < (int)upload_level_count; level++) {
                    TextureLevel *uploadLevel = &tex->faces[face].levels[level];
                    if (!mglTextureLevelHasUploadableCPUData(uploadLevel)) {
                        continue;
                    }

                    NSUInteger lvlWidth  = tex->faces[face].levels[level].width;
                    NSUInteger lvlHeight = tex->faces[face].levels[level].height;
                    NSUInteger lvlDepth  = tex->faces[face].levels[level].depth;
                    NSUInteger lvlPitch  = tex->faces[face].levels[level].pitch;
                    if (lvlPitch == 0 || lvlWidth == 0) continue;

                    if (is_array)
                    {
                        /* Array texture re-upload: loop over array layers and upload
                         * each slice independently.  Mirrors the DIRTY_TEXTURE_DATA
                         * array path (12861-13087).  The old code only uploaded
                         * slice 0 and passed the entire array's data_size as
                         * bytesPerImage with depth=num_layers, causing a crash in
                         * uploadTextureSliceViaBlit's newBufferWithBytes. */
                        GLuint num_layers = (tex_type == MTLTextureType1DArray || texture1DArrayBackedBy2DArray)
                            ? tex->faces[face].levels[level].height
                            : tex->faces[face].levels[level].depth;
                        if (num_layers == 0) continue;

                        BOOL arraySliceIs1D = (tex_type == MTLTextureType1DArray || texture1DArrayBackedBy2DArray);
                        NSUInteger uploadSliceHeight = arraySliceIs1D ? 1UL : MAX((NSUInteger)lvlHeight, 1UL);
                        NSUInteger baseBytesPerRow = lvlPitch;
                        NSUInteger uploadSliceRows = mglMetalUploadRowsForPixelFormat(pixelFormat, uploadSliceHeight);
                        if (uploadSliceRows == 0 || baseBytesPerRow > (NSUIntegerMax / uploadSliceRows)) {
                            NSLog(@"MGL WARNING: Re-upload array invalid row layout tex=%d face=%d level=%d bpr=%lu rows=%lu",
                                  tex->name,
                                  face,
                                  level,
                                  (unsigned long)baseBytesPerRow,
                                  (unsigned long)uploadSliceRows);
                            continue;
                        }
                        NSUInteger logicalBytesPerImage = baseBytesPerRow * uploadSliceRows;
                        NSUInteger backingBytes = tex->faces[face].levels[level].data_size;
                        if (num_layers > 1 && backingBytes >= (NSUInteger)num_layers) {
                            NSUInteger dividedLayerBytes = backingBytes / (NSUInteger)num_layers;
                            if (dividedLayerBytes >= logicalBytesPerImage) {
                                logicalBytesPerImage = dividedLayerBytes;
                            }
                        }

                        NSUInteger requiredArrayBytes = 0;
                        NSUInteger safeLayerCount = MAX((NSUInteger)num_layers, 1UL);
                        if (logicalBytesPerImage == 0 ||
                            logicalBytesPerImage > (NSUIntegerMax / safeLayerCount) ||
                            backingBytes < (requiredArrayBytes = logicalBytesPerImage * safeLayerCount)) {
                            NSLog(@"MGL WARNING: Re-upload array backing too small tex=%d face=%d level=%d backing=%lu layerBytes=%lu layers=%u",
                                  tex->name, face, level,
                                  (unsigned long)backingBytes,
                                  (unsigned long)logicalBytesPerImage,
                                  num_layers);
                            continue;
                        }

                        for (GLuint layer = 0; layer < num_layers; layer++)
                        {
                            size_t offset = logicalBytesPerImage * layer;
                            const void *layerSrcData = (const uint8_t *)tex->faces[face].levels[level].data + offset;
                            void *expandedUploadData = NULL;
                            NSUInteger effectiveBytesPerRow = baseBytesPerRow;
                            NSUInteger effectiveBytesPerImage = logicalBytesPerImage;

                            if (mglTextureInternalFormatNeedsRGBA8Expansion(tex->internalformat, pixelFormat)) {
                                NSUInteger expandedBPR = 0, expandedBPI = 0;
                                expandedUploadData = mglCreateRGBA8ExpandedUpload(tex,
                                                                                  (const uint8_t *)layerSrcData,
                                                                                  lvlWidth,
                                                                                  uploadSliceHeight,
                                                                                  baseBytesPerRow,
                                                                                  &expandedBPR,
                                                                                  &expandedBPI);
                                if (expandedUploadData) {
                                    layerSrcData = expandedUploadData;
                                    effectiveBytesPerRow = expandedBPR;
                                    effectiveBytesPerImage = expandedBPI;
                                }
                            } else if (mglTextureNeedsChannelExpansion(tex->internalformat, pixelFormat)) {
                                NSUInteger expandedBPR = 0, expandedBPI = 0;
                                expandedUploadData = mglCreateChannelExpandedUpload(tex,
                                                                                     pixelFormat,
                                                                                     (const uint8_t *)layerSrcData,
                                                                                     lvlWidth,
                                                                                     uploadSliceHeight,
                                                                                     baseBytesPerRow,
                                                                                     &expandedBPR,
                                                                                     &expandedBPI);
                                if (expandedUploadData) {
                                    layerSrcData = expandedUploadData;
                                    effectiveBytesPerRow = expandedBPR;
                                    effectiveBytesPerImage = expandedBPI;
                                }
                            }

                            NSUInteger alignment = [self getOptimalAlignmentForPixelFormat:pixelFormat];
                            NSUInteger alignedBytesPerRow = effectiveBytesPerRow;
                            if (alignedBytesPerRow % alignment != 0) {
                                alignedBytesPerRow = ((alignedBytesPerRow + alignment - 1) / alignment) * alignment;
                            }

                            uintptr_t addr = (uintptr_t)layerSrcData;
                            if (addr % alignment != 0 || alignedBytesPerRow != effectiveBytesPerRow) {
                                NSUInteger alignedUploadRows = mglMetalUploadRowsForPixelFormat(pixelFormat, uploadSliceHeight);
                                if (alignedUploadRows == 0 || alignedBytesPerRow > (NSUIntegerMax / alignedUploadRows)) {
                                    NSLog(@"MGL WARNING: Re-upload array rejecting aligned row layout bpr=%lu rows=%lu tex=%d face=%d level=%d layer=%u",
                                          (unsigned long)alignedBytesPerRow,
                                          (unsigned long)alignedUploadRows,
                                          tex->name,
                                          face,
                                          level,
                                          layer);
                                    free(expandedUploadData);
                                    continue;
                                }
                                NSUInteger alignedSize = alignedBytesPerRow * alignedUploadRows;
                                if (alignedSize > 0 && alignedSize <= (512 * 1024 * 1024)) {
                                    void *alignedData = aligned_alloc(alignment, alignedSize);
                                    if (alignedData) {
                                        memset(alignedData, 0, alignedSize);
                                        for (NSUInteger row = 0; row < alignedUploadRows; row++) {
                                            NSUInteger copySize = MIN(effectiveBytesPerRow, alignedBytesPerRow);
                                            memcpy((uint8_t *)alignedData + row * alignedBytesPerRow,
                                                   (const uint8_t *)layerSrcData + row * effectiveBytesPerRow, copySize);
                                        }
                                        [self uploadTextureSliceViaBlit:texture
                                                               texName:tex->name
                                                             texTarget:tex->target
                                                                 bytes:alignedData
                                                           bytesPerRow:alignedBytesPerRow
                                                         bytesPerImage:alignedSize
                                                                 width:lvlWidth
                                                                height:lvlHeight
                                                                 depth:1
                                                                 level:level
                                                                 slice:layer];
                                        free(alignedData);
                                    }
                                }
                            } else {
                                [self uploadTextureSliceViaBlit:texture
                                                       texName:tex->name
                                                     texTarget:tex->target
                                                         bytes:layerSrcData
                                                   bytesPerRow:effectiveBytesPerRow
                                                 bytesPerImage:effectiveBytesPerImage
                                                         width:lvlWidth
                                                        height:lvlHeight
                                                         depth:1
                                                         level:level
                                                         slice:layer];
                            }
                            free(expandedUploadData);
                        }
                    }
                    else
                    {
                    /* Non-array re-upload (2D, 3D, 1D, cube).
                     * For 3D textures, bytesPerImage must be a single 2D slice
                     * (bytesPerRow * height), NOT the full volume data_size.
                     * uploadTextureSliceViaBlit computes bufferSize =
                     * safeBytesPerImage * copyDepth, so passing the full volume
                     * as bytesPerImage AND depth would double-count and cause
                     * newBufferWithBytes to read past the source buffer. */
                    NSUInteger bytesPerRow = lvlPitch;
                    NSUInteger fullDataSize = tex->faces[face].levels[level].data_size;
                    if (fullDataSize == 0) fullDataSize = bytesPerRow * MAX((NSUInteger)lvlHeight, 1UL);

                    BOOL is3DReupload = (tex->target == GL_TEXTURE_3D && lvlDepth > 1);
                    NSUInteger singleSliceBPI = bytesPerRow * MAX((NSUInteger)lvlHeight, 1UL);
                    NSUInteger bytesPerImage = is3DReupload ? singleSliceBPI : fullDataSize;
                    NSUInteger uploadDepth = is3DReupload ? lvlDepth : (lvlDepth > 1 ? lvlDepth : 1);

                    const void *srcData = (const void *)tex->faces[face].levels[level].data;
                    void *expandedUploadData = NULL;
                    /* Channel expansion for 2D/non-3D only.  3D expansion would
                     * require per-slice handling (see DIRTY_TEXTURE_DATA 3D path). */
                    if (!is3DReupload) {
                        if (mglTextureInternalFormatNeedsRGBA8Expansion(tex->internalformat, pixelFormat)) {
                            NSUInteger expandedBytesPerRow = 0;
                            NSUInteger expandedBytesPerImage = 0;
                            expandedUploadData = mglCreateRGBA8ExpandedUpload(tex,
                                                                              (const uint8_t *)srcData,
                                                                              lvlWidth,
                                                                              MAX((NSUInteger)lvlHeight, 1UL),
                                                                              bytesPerRow,
                                                                              &expandedBytesPerRow,
                                                                              &expandedBytesPerImage);
                            if (expandedUploadData) {
                                srcData = expandedUploadData;
                                bytesPerRow = expandedBytesPerRow;
                                bytesPerImage = expandedBytesPerImage;
                            }
                        } else if (mglTextureNeedsChannelExpansion(tex->internalformat, pixelFormat)) {
                            NSUInteger expandedBytesPerRow = 0;
                            NSUInteger expandedBytesPerImage = 0;
                            expandedUploadData = mglCreateChannelExpandedUpload(tex,
                                                                                 pixelFormat,
                                                                                 (const uint8_t *)srcData,
                                                                                 lvlWidth,
                                                                                 MAX((NSUInteger)lvlHeight, 1UL),
                                                                                 bytesPerRow,
                                                                                 &expandedBytesPerRow,
                                                                                 &expandedBytesPerImage);
                            if (expandedUploadData) {
                                srcData = expandedUploadData;
                                bytesPerRow = expandedBytesPerRow;
                                bytesPerImage = expandedBytesPerImage;
                            }
                        }
                    }
                    NSUInteger alignment = [self getOptimalAlignmentForPixelFormat:pixelFormat];
                    NSUInteger alignedBytesPerRow = bytesPerRow;
                    if (alignedBytesPerRow % alignment != 0) {
                        alignedBytesPerRow = ((alignedBytesPerRow + alignment - 1) / alignment) * alignment;
                    }

                    uintptr_t addr = (uintptr_t)srcData;
                    if (addr % alignment != 0 || alignedBytesPerRow != bytesPerRow) {
                        NSUInteger rowCount = MAX((NSUInteger)lvlHeight, 1UL);
                        NSUInteger alignedSliceBPI = alignedBytesPerRow * rowCount;
                        NSUInteger alignedSize = alignedSliceBPI * uploadDepth;
                        if (alignedSize > 0 && alignedSize <= (512 * 1024 * 1024)) {
                            void *alignedData = aligned_alloc(alignment, alignedSize);
                            if (alignedData) {
                                memset(alignedData, 0, alignedSize);
                                for (NSUInteger z = 0; z < uploadDepth; z++) {
                                    for (NSUInteger row = 0; row < rowCount; row++) {
                                        NSUInteger copySize = MIN(bytesPerRow, alignedBytesPerRow);
                                        memcpy((uint8_t *)alignedData + z * alignedSliceBPI + row * alignedBytesPerRow,
                                               (const uint8_t *)srcData + z * singleSliceBPI + row * bytesPerRow, copySize);
                                    }
                                }
                                [self uploadTextureSliceViaBlit:texture
                                                       texName:tex->name
                                                     texTarget:tex->target
                                                         bytes:alignedData
                                                   bytesPerRow:alignedBytesPerRow
                                                 bytesPerImage:alignedSliceBPI
                                                         width:lvlWidth
                                                        height:lvlHeight
                                                         depth:uploadDepth
                                                         level:level
                                                         slice:face];
                                free(alignedData);
                            }
                        }
                    } else {
                        [self uploadTextureSliceViaBlit:texture
                                               texName:tex->name
                                             texTarget:tex->target
                                                 bytes:srcData
                                           bytesPerRow:bytesPerRow
                                         bytesPerImage:bytesPerImage
                                                 width:lvlWidth
                                                height:lvlHeight
                                                 depth:uploadDepth
                                                 level:level
                                                 slice:face];
                    }
                    free(expandedUploadData);
                    } /* end else (non-array) */
                }
            }
        } else if (tex->is_render_target || mglMetalPixelFormatIsDepthOrStencil(pixelFormat)) {
            static uint64_t s_skipRenderTargetFillLogs = 0;
            uint64_t hit = ++s_skipRenderTargetFillLogs;
            if (hit <= 64ull || (hit % 512ull) == 0ull) {
                NSLog(@"MGL TEXTURE SKIP implicit fill tex=%u renderTarget=%u format=%lu sourceSafe=0 hit=%llu",
                      (unsigned)tex->name,
                      (unsigned)tex->is_render_target,
                      (unsigned long)pixelFormat,
                      (unsigned long long)hit);
            }
        } else {
            // No existing data — fill with safe initial contents
        if (texture.width == 0 || texture.height == 0 || texture.width > 16384 || texture.height > 16384) {
            NSLog(@"MGL WARNING: Skipping texture fill due to invalid dimensions: %lux%lu", (unsigned long)texture.width, (unsigned long)texture.height);
        } else {
            // Determine pixel format size to create appropriate black data
            NSUInteger bytesPerPixel = 4; // Default to RGBA
            switch(texture.pixelFormat) {
                case MTLPixelFormatR8Unorm:
                case MTLPixelFormatR8Uint:
                case MTLPixelFormatR8Sint:
                    bytesPerPixel = 1;
                    break;
                case MTLPixelFormatRG8Unorm:
                case MTLPixelFormatRG8Uint:
                case MTLPixelFormatRG8Sint:
                    bytesPerPixel = 2;
                    break;
                case MTLPixelFormatRGBA8Unorm:
                case MTLPixelFormatRGBA8Uint:
                case MTLPixelFormatRGBA8Sint:
                    bytesPerPixel = 4;
                    break;
                default:
                    bytesPerPixel = 4; // Default assumption
                    break;
            }

            // Calculate dynamic alignment for Metal textures based on pixel format
            NSUInteger bytesPerRow = texture.width * bytesPerPixel;
            NSUInteger alignment = [self getOptimalAlignmentForPixelFormat:texture.pixelFormat];
            if (bytesPerRow % alignment != 0) {
                bytesPerRow = ((bytesPerRow + alignment - 1) / alignment) * alignment;
            }

            NSUInteger dataSize = bytesPerRow * texture.height;

            // Validate that dataSize is reasonable (not too large)
            if (dataSize > 64 * 1024 * 1024) { // 64MB limit per texture level
                NSLog(@"MGL WARNING: Skipping texture fill due to excessive size: %lu bytes", (unsigned long)dataSize);
            } else {
                // Allocate initialization data for texture clear.
                // aligned_alloc has been unreliable in this environment; calloc is safer here.
                (void)alignment;
                void *blackData = calloc(dataSize, 1);
                if (blackData) {
                    // CRITICAL SECURITY FIX: Comprehensive validation to prevent Metal driver crashes
                    // calloc already zero-initializes

                    // Multi-layer validation for all parameters
                    if (!blackData) {
                        NSLog(@"MGL SECURITY ERROR: blackData is NULL after memset - CORRUPTION DETECTED");
                        return texture;
                    }
                    if (bytesPerRow == 0) {
                        NSLog(@"MGL SECURITY ERROR: Invalid bytesPerRow (0) for texture fill");
                        free(blackData);
                        return texture;
                    }
                    if (dataSize == 0) {
                        NSLog(@"MGL SECURITY ERROR: Invalid dataSize (0) for texture fill");
                        free(blackData);
                        return texture;
                    }
                    if (!texture) {
                        NSLog(@"MGL SECURITY ERROR: Metal texture is NULL");
                        free(blackData);
                        return texture;
                    }
                    if (texture.width == 0 || texture.height == 0) {
                        NSLog(@"MGL SECURITY ERROR: Invalid texture dimensions %lux%lu", (unsigned long)texture.width, (unsigned long)texture.height);
                        free(blackData);
                        return texture;
                    }

                    // Additional validation: verify blackData contains expected zeros (anti-corruption check)
                    uint8_t *bytes = (uint8_t *)blackData;
                    bool dataCorrupted = false;
                    for (NSUInteger i = 0; i < MIN(dataSize, 1024); i++) { // Check first 1KB only for performance
                        if (bytes[i] != 0) {
                            dataCorrupted = true;
                            break;
                        }
                    }
                    if (dataCorrupted) {
                        NSLog(@"MGL SECURITY ERROR: blackData corruption detected - memory safety issue");
                        free(blackData);
                        return texture;
                    }

                    NSLog(@"MGL INFO: All validations passed for texture fill (size=%lu, bytesPerRow=%lu)", (unsigned long)dataSize, (unsigned long)bytesPerRow);

                    // ULTRA-DEFENSIVE: Final validation immediately before Metal API call
                    // This prevents race conditions and memory corruption between validation and use
                    if (!blackData) {
                        NSLog(@"MGL CRITICAL ERROR: blackData became NULL before Metal call - RACE CONDITION DETECTED");
                        free(blackData);
                        return texture;
                    }
                    if (!texture) {
                        NSLog(@"MGL CRITICAL ERROR: Metal texture became NULL before Metal call - RACE CONDITION DETECTED");
                        free(blackData);
                        return texture;
                    }
                    if (bytesPerRow == 0 || dataSize == 0) {
                        NSLog(@"MGL CRITICAL ERROR: Parameters became invalid before Metal call - RACE CONDITION DETECTED");
                        free(blackData);
                        return texture;
                    }

                    // Additional verification: Check if Metal texture is still valid
                    if (texture.width == 0 || texture.height == 0) {
                        NSLog(@"MGL CRITICAL ERROR: Metal texture dimensions became invalid before Metal call");
                        free(blackData);
                        return texture;
                    }

                    // Final integrity check: Verify blackData still contains expected zeros
                    uint8_t *finalCheck = (uint8_t *)blackData;
                    bool finalCorruption = false;
                    for (NSUInteger i = 0; i < MIN(dataSize, 256); i++) { // Check first 256 bytes
                        if (finalCheck[i] != 0) {
                            finalCorruption = true;
                            break;
                        }
                    }
                    if (finalCorruption) {
                        NSLog(@"MGL CRITICAL ERROR: Memory corruption detected immediately before Metal call");
                        free(blackData);
                        return texture;
                    }

                    NSLog(@"MGL INFO: FIXING: Implementing proper texture filling for Apple Metal compatibility");

                    // PROPER FIX: Use Apple Metal-compatible texture filling approach
                    // The issue was using incorrect bytesPerRow and region parameters
                    NSLog(@"MGL INFO: Implementing Metal-compliant texture fill operations");

                    // Use Metal's standard pattern for texture filling.
                    NSUInteger pixelSize = bytesPerPixel;
                    NSUInteger properBytesPerRow = width * pixelSize;

                    // Ensure proper alignment for Apple Metal driver
                    if (properBytesPerRow % 64 != 0) {
                        properBytesPerRow = ((properBytesPerRow + 63) / 64) * 64;
                    }

                    // Fill the entire level. A previous 1x1 safety fill left large textures
                    // mostly uninitialized while their Metal backing existed.
                    MTLRegion properRegion = MTLRegionMake2D(0, 0, width, height);

                    // Create properly aligned texture data buffer
                    NSUInteger fillSize = properBytesPerRow * properRegion.size.height;
                    uint8_t *properData = (uint8_t *)calloc(fillSize, 1);

                    if (properData) {
                        // Initialize with safe texture data (transparent black with alpha = 0)
                        for (NSUInteger y = 0; y < properRegion.size.height; y++) {
                            uint8_t *row = properData + (y * properBytesPerRow);
                            for (NSUInteger x = 0; x < properRegion.size.width; x++) {
                                uint8_t *pixel = row + (x * pixelSize);
                                pixel[0] = 0;  // R
                                if (pixelSize > 1) pixel[1] = 0;  // G
                                if (pixelSize > 2) pixel[2] = 0;  // B
                                if (pixelSize > 3) pixel[3] = 0; // A = transparent for uninitialized color data
                            }
                        }

                        @try {
                            NSLog(@"MGL INFO: Performing Metal-compliant texture fill:");
                            NSLog(@"  - Region: %dx%d", (int)properRegion.size.width, (int)properRegion.size.height);
                            NSLog(@"  - bytesPerRow: %lu", (unsigned long)properBytesPerRow);
                            NSLog(@"  - dataSize: %lu", (unsigned long)fillSize);

                            // ALTERNATIVE APPROACH: Safe texture filling without replaceRegion
                            NSLog(@"MGL INFO: Using alternative texture filling methods (AGX-safe)");

                            @try {
                                // ALTERNATIVE 1: Try MTLBuffer-to-texture copy approach
                                if (properData && dataSize > 0) {
                                    NSLog(@"MGL INFO: Attempting buffer-based texture fill");

                                    // Create a temporary MTLBuffer with the texture data
                                    id<MTLBuffer> tempBuffer = [_device newBufferWithBytes:properData
                                                                                    length:fillSize
                                                                                   options:MTLResourceStorageModeShared];

                                    if (tempBuffer) {
                                        NSLog(@"MGL INFO: Created temporary MTLBuffer for texture data");

                                        if ([self shouldSkipGPUOperations]) {
                                            NSLog(@"MGL AGX: Skipping texture fill during recovery - texture will be empty");
                                        } else {
                                            BOOL uploaded = [self copyTextureUploadWithDedicatedCommandBuffer:tempBuffer
                                                                                                  sourceOffset:0
                                                                                             sourceBytesPerRow:properBytesPerRow
                                                                                           sourceBytesPerImage:fillSize
                                                                                                     sourceSize:MTLSizeMake(properRegion.size.width, properRegion.size.height, 1)
                                                                                                      toTexture:texture
                                                                                               destinationSlice:0
                                                                                               destinationLevel:0
                                                                                              destinationOrigin:MTLOriginMake(0, 0, 0)
                                                                                                         reason:"texture_fill_initialization"];
                                            if (uploaded) {
                                                NSLog(@"MGL SUCCESS: Texture data copied using dedicated upload command buffer");
                                                mglMarkTextureLevelMetalFilled(tex, 0, fillSize);
                                            } else {
                                                NSLog(@"MGL WARNING: Dedicated texture fill upload failed - texture may remain uninitialized");
                                            }
                                        }

                                        // Clean up the temporary buffer
                                        tempBuffer = nil;
                                    }
                                }
                            } @catch (NSException *exception) {
                                NSLog(@"MGL WARNING: Buffer-based texture fill failed - trying alternative");

                                // ALTERNATIVE 2: Simple direct color filling for basic cases
                                if (width <= 512 && height <= 512 && tex->internalformat == GL_RGBA8) {
                                    NSLog(@"MGL INFO: Attempting simple direct color fill for small RGBA8 texture");

                                    @try {
                                        // Create a simple pattern that's not magenta
                                        NSUInteger pixelCount = width * height;
                                        uint32_t *simpleData = calloc(pixelCount, sizeof(uint32_t));

                                        if (simpleData) {
                                            // Create a simple gradient pattern instead of magenta
                                            for (NSUInteger y = 0; y < height; y++) {
                                                for (NSUInteger x = 0; x < width; x++) {
                                                    NSUInteger index = y * width + x;

                                                    // Create a simple gradient from blue to green
                                                    uint8_t r = (uint8_t)(x * 255 / width);
                                                    uint8_t g = (uint8_t)(y * 255 / height);
                                                    uint8_t b = 128;
                                                    uint8_t a = 255;

                                                    simpleData[index] = (a << 24) | (b << 16) | (g << 8) | r;
                                                }
                                            }

                                            // Try direct replaceRegion for simple cases
                                            MTLRegion simpleRegion = MTLRegionMake2D(0, 0, width, height);
                                            [texture replaceRegion:simpleRegion
                                                    mipmapLevel:0
                                                          slice:0
                                                      withBytes:simpleData
                                                    bytesPerRow:width * sizeof(uint32_t)
                                                  bytesPerImage:width * height * sizeof(uint32_t)];

                                            NSLog(@"MGL SUCCESS: Simple direct color fill completed");
                                            mglMarkTextureLevelMetalFilled(tex, 0, pixelCount * sizeof(uint32_t));
                                            free(simpleData);
                                        }
                                    } @catch (NSException *exception) {
                                        NSLog(@"MGL WARNING: Simple direct fill also failed: %@", exception.reason);
                                    }
                                } else {
                                    NSLog(@"MGL INFO: Skipping complex texture - would use deferred initialization");
                                }
                            }
                        } @catch (NSException *exception) {
                            NSLog(@"MGL ERROR: Metal texture fill failed - investigating root cause");
                            NSLog(@"MGL ERROR: Exception: %@ (Reason: %@)", exception.name, exception.reason);
                            NSLog(@"MGL INFO: This indicates our parameters are still incompatible with AGX driver");
                        }

                        free(properData);
                    } else {
                        NSLog(@"MGL ERROR: Failed to allocate properly aligned texture data");
                    }
                    free(blackData);
                } else {
                    NSLog(@"MGL ERROR: Failed to allocate aligned memory for texture fill (%lu bytes)", (unsigned long)dataSize);
                }
            }
        }
    } // end hasExistingLevelData else (black fill)
    }

    if (cpuUploadRequired && tex->target == GL_TEXTURE_2D && texture.textureType == MTLTextureType2D) {
        cpuUploadVerified = [self uploadFullCPUTextureDataIntoTexture:tex
                                                                 metal:texture
                                                                reason:"createMTLTexture.cpuData"];
    } else if (cpuUploadRequired) {
        /*
         * Non-2D uploads still use the legacy creation path above. The current GUI
         * atlas failure is 2D; avoid changing array/cube semantics in this pass.
         */
        cpuUploadVerified = YES;
    }

    if (cpuUploadRequired && !cpuUploadVerified) {
        static uint64_t s_createTextureCPUUploadIncompleteLogs = 0;
        uint64_t hit = ++s_createTextureCPUUploadIncompleteLogs;
        if (hit <= 64ull || (hit % 512ull) == 0ull) {
            TextureLevel *level0 = mglTraceTextureBaseLevel(tex);
            NSLog(@"MGL TEXTURE CREATE CPU-UPLOAD INCOMPLETE tex=%u target=0x%x dirtyBefore=0x%x level0=%ux%u source=%u upload=%lu hit=%llu",
                  (unsigned)tex->name,
                  (unsigned)tex->target,
                  (unsigned)tex->dirty_bits,
                  level0 ? (unsigned)level0->width : 0u,
                  level0 ? (unsigned)level0->height : 0u,
                  level0 ? (unsigned)level0->last_init_source : 0u,
                  (unsigned long)(level0 ? level0->last_upload_size : 0u),
                  (unsigned long long)hit);
        }
        tex->dirty_bits &= ~(DIRTY_TEXTURE_LEVEL | DIRTY_TEXTURE_ACCESS);
        tex->dirty_bits |= DIRTY_TEXTURE_DATA;
    } else {
        tex->dirty_bits = 0;
    }

    /* Diagnostic: log Metal texture mipmap state and per-level upload summary
     * to diagnose Minecraft "gray + moiré" texture issues. */
    {
        static uint64_t s_mipDiagLogs = 0;
        uint64_t diagHit = ++s_mipDiagLogs;
        if (kMGLDiagnosticStateLogs &&
            (diagHit <= 128ull || (diagHit % 512ull) == 0ull)) {
            NSUInteger mtlMipCount = texture.mipmapLevelCount;
            MTLPixelFormat mtlFmt = texture.pixelFormat;
            MTLStorageMode mtlStorage = texture.storageMode;
            NSUInteger uploadedLevels = 0;
            NSUInteger skippedLevels = 0;
            NSUInteger skippedSourceNone = 0;
            NSUInteger skippedNoData = 0;
            NSMutableString *levelSummary = [NSMutableString stringWithCapacity:256];
            NSUInteger levelsToSummarize = MIN((NSUInteger)tex->num_levels, (NSUInteger)16);
            for (NSUInteger lvl = 0; lvl < levelsToSummarize; lvl++) {
                TextureLevel *tl = (tex->faces[0].levels && lvl < tex->num_levels)
                    ? &tex->faces[0].levels[lvl] : NULL;
                if (!tl) { [levelSummary appendString:@"-"]; continue; }
                bool uploadable = mglTextureLevelHasUploadableCPUData(tl);
                if (uploadable) uploadedLevels++; else skippedLevels++;
                if (!uploadable) {
                    if (tl->last_init_source == kTexImageNull || tl->last_init_source == kTexInitNone)
                        skippedSourceNone++;
                    if (!tl->has_initialized_data && !tl->ever_written)
                        skippedNoData++;
                }
                [levelSummary appendFormat:@"[%u:s%u:w%u:e%u:i%u]",
                    (unsigned)lvl, (unsigned)tl->last_init_source,
                    (unsigned)tl->width, (unsigned)tl->ever_written,
                    (unsigned)tl->has_initialized_data];
            }
            MGLTraceNSLog(@"MGL TEX_MIP_DIAG tex=%u target=0x%x dims=%ux%u internal=0x%x "
                          @"numLevels=%u mipmapLevels=%u effectiveMipLevels=%u mtlMipCount=%lu "
                          @"mtlFmt=%lu mtlStorage=%ld mipmapped=%d baseLevel=%u maxLevel=%u "
                          @"uploadedLevels=%lu skippedLevels=%lu skippedSourceNone=%lu skippedNoData=%lu "
                          @"levels=%@ hit=%llu",
                          (unsigned)tex->name, (unsigned)tex->target,
                          (unsigned)tex->width, (unsigned)tex->height,
                          (unsigned)tex->internalformat,
                          (unsigned)tex->num_levels, (unsigned)tex->mipmap_levels,
                          (unsigned)effective_mipmap_levels, (unsigned long)mtlMipCount,
                          (unsigned long)mtlFmt, (long)mtlStorage, (int)(tex->mipmapped ? 1 : 0),
                          (unsigned)tex->params.base_level, (unsigned)tex->params.max_level,
                          (unsigned long)uploadedLevels, (unsigned long)skippedLevels,
                          (unsigned long)skippedSourceNone, (unsigned long)skippedNoData,
                          levelSummary, (unsigned long long)diagHit);
        }
    }

    // Record successful texture creation for AGX error tracking
    [self recordGPUSuccess];

    return texture;
}

// AGX-SAFE Fallback texture creation for GPU error recovery scenarios
- (id<MTLTexture>) createFallbackMTLTexture:(Texture *) tex
{
    // Validate texture parameters before creating Metal texture to prevent Metal assertion failures
    if (!tex || tex->width <= 0 || tex->height <= 0 || tex->width > 32768 || tex->height > 32768) {
        NSLog(@"MGL AGX: Skipping fallback texture creation - invalid dimensions %dx%d",
              tex ? tex->width : 0, tex ? tex->height : 0);
        return nil;
    }

    NSLog(@"MGL AGX: Creating emergency fallback texture (size: %dx%dx%d)", tex->width, tex->height, tex->depth);

    @try {
        MTLPixelFormat fallbackFormat = mtlPixelFormatForGLTex(tex);
        if (fallbackFormat == MTLPixelFormatInvalid) {
            // Conservative defaults by GL intent when translation is unavailable.
            if (tex->internalformat == GL_DEPTH24_STENCIL8 ||
                tex->internalformat == GL_DEPTH32F_STENCIL8) {
                fallbackFormat = MTLPixelFormatDepth32Float_Stencil8;
            } else if (tex->internalformat == GL_DEPTH_COMPONENT ||
                       tex->internalformat == GL_DEPTH_COMPONENT16 ||
                       tex->internalformat == GL_DEPTH_COMPONENT24 ||
                       tex->internalformat == GL_DEPTH_COMPONENT32 ||
                       tex->internalformat == GL_DEPTH_COMPONENT32F) {
                fallbackFormat = MTLPixelFormatDepth32Float;
            } else {
                fallbackFormat = MTLPixelFormatRGBA8Unorm;
            }
        }

        BOOL isDepthOrStencilFormat =
            (fallbackFormat == MTLPixelFormatDepth16Unorm ||
             fallbackFormat == MTLPixelFormatDepth32Float ||
             fallbackFormat == MTLPixelFormatDepth24Unorm_Stencil8 ||
             fallbackFormat == MTLPixelFormatDepth32Float_Stencil8 ||
             fallbackFormat == MTLPixelFormatStencil8);

        MTLTextureDescriptor *fallbackDesc = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:fallbackFormat
                                                                                                    width:MAX(tex->width, 1)
                                                                                                   height:MAX(tex->height, 1)
                                                                                                mipmapped:NO];
        fallbackDesc.usage = MTLTextureUsageShaderRead;
        if (tex->is_render_target || isDepthOrStencilFormat) {
            fallbackDesc.usage |= MTLTextureUsageRenderTarget;
        }
        fallbackDesc.storageMode = MTLStorageModeShared;

        id<MTLTexture> fallbackTexture = [_device newTextureWithDescriptor:fallbackDesc];

        if (fallbackTexture) {
            // Fill with simple gradient pattern using a simple approach
            NSUInteger width = fallbackTexture.width;
            NSUInteger height = fallbackTexture.height;

            if (!isDepthOrStencilFormat && width <= 512 && height <= 512) {
                uint32_t *gradientData = calloc(width * height, sizeof(uint32_t));
                if (gradientData) {
                    // Create simple red-blue gradient
                    for (NSUInteger y = 0; y < height; y++) {
                        for (NSUInteger x = 0; x < width; x++) {
                            NSUInteger index = y * width + x;
                            uint8_t r = (uint8_t)((x * 255) / width);
                            uint8_t g = 128;
                            uint8_t b = (uint8_t)((y * 255) / height);
                            uint8_t a = 255;
                            gradientData[index] = ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)g << 8) | (uint32_t)r;
                        }
                    }

                    MTLRegion region = MTLRegionMake2D(0, 0, width, height);
                    [fallbackTexture replaceRegion:region mipmapLevel:0 withBytes:gradientData
                               bytesPerRow:width * sizeof(uint32_t)];

                    free(gradientData);
                    NSLog(@"MGL AGX: Fallback color texture created with gradient pattern");
                }
            }
        }

        return fallbackTexture;

    } @catch (NSException *exception) {
        NSLog(@"MGL AGX: Even fallback texture creation failed: %@", exception.reason);
        return nil;
    }
}

// Helper function to calculate bytes per pixel for different OpenGL formats
- (NSUInteger)bytesPerPixelForFormat:(GLenum)internalformat
{
    switch(internalformat) {
        case GL_RED:
        case GL_R8:
        case GL_R8I:
        case GL_R8UI:
            return 1;

        case GL_RG:
        case GL_RG8:
        case GL_RG8I:
        case GL_RG8UI:
        case GL_R16:
        case GL_R16F:
        case GL_R16I:
        case GL_R16UI:
            return 2;

        case GL_RGB:
        case GL_RGB8:
        case GL_RGB8I:
        case GL_RGB8UI:
        case GL_SRGB8:
        case GL_R11F_G11F_B10F:
        case GL_RGB9_E5:
            return 3;

        case GL_RGBA:
        case GL_RGBA8:
        case GL_RGBA8I:
        case GL_RGBA8UI:
        case GL_RGB10_A2:
        case GL_RGB10_A2UI:
        case GL_SRGB8_ALPHA8:
        case GL_RG16I:
        case GL_RG16UI:
        case GL_R32I:
        case GL_R32UI:
        case GL_R32F:
            return 4;

        case GL_RGBA16:
        case GL_RGBA16F:
        case GL_RG32I:
        case GL_RG32UI:
        case GL_RG32F:
            return 8;

        case GL_RGB16:
        case GL_RGB16F:
            return 6;

        case GL_RGBA16I:
        case GL_RGBA16UI:
            return 8;

        case GL_RGB32F:
        case GL_RGB32I:
        case GL_RGB32UI:
            return 12;

        case GL_RGBA32F:
        case GL_RGBA32I:
        case GL_RGBA32UI:
            return 16;

        default:
            // Default to 4 bytes for unknown formats
            NSLog(@"MGL WARNING: Unknown internal format 0x%x, defaulting to 4 bytes per pixel", internalformat);
            return 4;
    }
}

- (id<MTLSamplerState>) createMTLSamplerForTexParam:(TextureParameter *)tex_param target:(GLuint)target
{
    MTLSamplerDescriptor *samplerDescriptor;

    if (!tex_param) {
        NSLog(@"MGL SAMPLER ERROR: createMTLSamplerForTexParam called with NULL parameters");
        return nil;
    }

    samplerDescriptor = [MTLSamplerDescriptor new];
    if (!samplerDescriptor) {
        NSLog(@"MGL SAMPLER ERROR: failed to allocate MTLSamplerDescriptor");
        return nil;
    }

    switch(tex_param->min_filter)
    {
        case GL_NEAREST:
            samplerDescriptor.minFilter = MTLSamplerMinMagFilterNearest;
            break;

        case GL_LINEAR:
            samplerDescriptor.minFilter = MTLSamplerMinMagFilterLinear;
            break;

        case GL_NEAREST_MIPMAP_NEAREST:
            samplerDescriptor.minFilter = MTLSamplerMinMagFilterNearest;
            samplerDescriptor.mipFilter = MTLSamplerMipFilterNearest;
            break;

        case GL_LINEAR_MIPMAP_NEAREST:
            samplerDescriptor.minFilter = MTLSamplerMinMagFilterLinear;
            samplerDescriptor.mipFilter = MTLSamplerMipFilterNearest;
            break;

        case GL_NEAREST_MIPMAP_LINEAR:
            samplerDescriptor.minFilter = MTLSamplerMinMagFilterNearest;
            samplerDescriptor.mipFilter = MTLSamplerMipFilterLinear;
            break;

        case GL_LINEAR_MIPMAP_LINEAR:
            samplerDescriptor.minFilter = MTLSamplerMinMagFilterLinear;
            samplerDescriptor.mipFilter = MTLSamplerMipFilterLinear;
            break;

        default:
            NSLog(@"MGL SAMPLER ERROR: invalid GL_TEXTURE_MIN_FILTER 0x%x", tex_param->min_filter);
            return nil;
    }

    switch(tex_param->mag_filter)
    {
        case GL_NEAREST:
            samplerDescriptor.magFilter = MTLSamplerMinMagFilterNearest;
            break;

        case GL_LINEAR:
            samplerDescriptor.magFilter = MTLSamplerMinMagFilterLinear;
            break;

        default:
            NSLog(@"MGL SAMPLER ERROR: invalid GL_TEXTURE_MAG_FILTER 0x%x", tex_param->mag_filter);
            return nil;
    }

    //     @property (nonatomic) NSUInteger maxAnisotropy;
    if (tex_param->max_anisotropy > 1.0)
    {
        samplerDescriptor.maxAnisotropy = tex_param->max_anisotropy;
    }

    //    @property (nonatomic) MTLSamplerAddressMode sAddressMode;
    //    @property (nonatomic) MTLSamplerAddressMode tAddressMode;
    //    @property (nonatomic) MTLSamplerAddressMode rAddressMode;
    for (int i=0; i<3; i++)
    {
        MTLSamplerAddressMode mode = 0;
        GLenum type = 0;

        switch(i)
        {
            case 0: type = tex_param->wrap_s; break;
            case 1: type = tex_param->wrap_t; break;
            case 2: type = tex_param->wrap_r; break;
        }

        switch(type)
        {
            case GL_CLAMP_TO_EDGE:
                mode = MTLSamplerAddressModeClampToEdge;
                break;

            case GL_CLAMP_TO_BORDER:
                mode = MTLSamplerAddressModeClampToBorderColor;
                break;

            case GL_MIRRORED_REPEAT:
                mode = MTLSamplerAddressModeMirrorRepeat;
                break;

            case GL_REPEAT:
                mode = MTLSamplerAddressModeRepeat;
                break;

            case GL_MIRROR_CLAMP_TO_EDGE:
                mode = MTLSamplerAddressModeMirrorClampToEdge;
                break;

    //        case GL_CLAMP_TO_ZERO_MGL_EXT:
    //            mode = MTLSamplerAddressModeClampToZero;
    //            break;

            default:
                NSLog(@"MGL SAMPLER ERROR: invalid GL texture wrap mode 0x%x for axis %d", type, i);
                return nil;
        }

        switch(i)
        {
            case 0: samplerDescriptor.sAddressMode = mode; break;
            case 1: samplerDescriptor.tAddressMode = mode; break;
            case 2: samplerDescriptor.rAddressMode = mode; break;
        }
    }

    BOOL usesBorderColor = (tex_param->wrap_s == GL_CLAMP_TO_BORDER ||
                            tex_param->wrap_t == GL_CLAMP_TO_BORDER ||
                            tex_param->wrap_r == GL_CLAMP_TO_BORDER);
    if (!usesBorderColor)
    {
        samplerDescriptor.borderColor = MTLSamplerBorderColorTransparentBlack;
    }
    else if ((tex_param->border_color[0] == 0.0) &&
             (tex_param->border_color[1] == 0.0) &&
             (tex_param->border_color[2] == 0.0) &&
             (tex_param->border_color[3] == 0.0))
    {
        samplerDescriptor.borderColor = MTLSamplerBorderColorTransparentBlack;
    }
    else if ((tex_param->border_color[0] == 0.0) &&
             (tex_param->border_color[1] == 0.0) &&
             (tex_param->border_color[2] == 0.0) &&
             (tex_param->border_color[3] == 1.0))
    {
        samplerDescriptor.borderColor = MTLSamplerBorderColorOpaqueBlack;
    }
    else if ((tex_param->border_color[0] == 1.0) &&
             (tex_param->border_color[1] == 1.0) &&
             (tex_param->border_color[2] == 1.0) &&
             (tex_param->border_color[3] == 1.0))
    {
        samplerDescriptor.borderColor = MTLSamplerBorderColorOpaqueWhite;
    }
    else
    {
        static uint64_t s_unsupportedBorderColorCount = 0;
        uint64_t hit = ++s_unsupportedBorderColorCount;
        if (hit <= 32ull || (hit % 256ull) == 0ull) {
            NSLog(@"MGL SAMPLER WARNING: GL border color (%g,%g,%g,%g) is not exactly representable by MTLSamplerBorderColor; approximating hit=%llu",
                  tex_param->border_color[0],
                  tex_param->border_color[1],
                  tex_param->border_color[2],
                  tex_param->border_color[3],
                  (unsigned long long)hit);
        }

        if (tex_param->border_color[3] < 0.5f) {
            samplerDescriptor.borderColor = MTLSamplerBorderColorTransparentBlack;
        } else if (tex_param->border_color[0] >= 0.5f &&
                   tex_param->border_color[1] >= 0.5f &&
                   tex_param->border_color[2] >= 0.5f) {
            samplerDescriptor.borderColor = MTLSamplerBorderColorOpaqueWhite;
        } else {
            samplerDescriptor.borderColor = MTLSamplerBorderColorOpaqueBlack;
        }
    }

    if (target == GL_TEXTURE_RECTANGLE)
    {
        samplerDescriptor.normalizedCoordinates = false;
        if ((tex_param->wrap_s != GL_CLAMP_TO_EDGE) ||
            (tex_param->wrap_t != GL_CLAMP_TO_EDGE) ||
            (tex_param->wrap_r != GL_CLAMP_TO_EDGE))
        {
            static uint64_t s_rectWrapClampWarningCount = 0;
            uint64_t hit = ++s_rectWrapClampWarningCount;
            if (hit <= 16ull || (hit % 256ull) == 0ull) {
                NSLog(@"MGL SAMPLER WARNING: GL_TEXTURE_RECTANGLE requires unnormalized coordinates; forcing ClampToEdge sampler address modes for Metal compatibility hit=%llu",
                      (unsigned long long)hit);
            }
            samplerDescriptor.sAddressMode = MTLSamplerAddressModeClampToEdge;
            samplerDescriptor.tAddressMode = MTLSamplerAddressModeClampToEdge;
            samplerDescriptor.rAddressMode = MTLSamplerAddressModeClampToEdge;
        }
    }

    // @property (nonatomic) BOOL lodAverage API_AVAILABLE(ios(9.0), macos(11.0), macCatalyst(14.0));


    // @property (nonatomic) MTLCompareFunction compareFunction API_AVAILABLE(macos(10.11), ios(9.0));
    if (tex_param->compare_mode == GL_NONE)
    {
        samplerDescriptor.compareFunction = MTLCompareFunctionNever;
    }
    else if (tex_param->compare_mode == GL_COMPARE_REF_TO_TEXTURE)
    {
        if (!mglIsValidGLCompareFunction(tex_param->compare_func))
        {
            NSLog(@"MGL SAMPLER ERROR: invalid GL_TEXTURE_COMPARE_FUNC 0x%x", tex_param->compare_func);
            return nil;
        }
        samplerDescriptor.compareFunction =
            mglMTLCompareFunctionForGL(tex_param->compare_func,
                                       MTLCompareFunctionNever,
                                       "sampler");
    }
    else
    {
        NSLog(@"MGL SAMPLER ERROR: invalid GL_TEXTURE_COMPARE_MODE 0x%x", tex_param->compare_mode);
        return nil;
    }

    /* Apply GL_TEXTURE_MIN_LOD / GL_TEXTURE_MAX_LOD as Metal lod clamps.
     * GL defaults: min_lod=-1000, max_lod=1000 (effectively unclamped).
     * Metal's lodMinClamp cannot be negative (minimum 0.0), so clamp to 0.0
     * unconditionally rather than only when the GL default sentinel is seen. */
    samplerDescriptor.lodMinClamp = (tex_param->min_lod < 0.0f) ? 0.0f : tex_param->min_lod;
    samplerDescriptor.lodMaxClamp = (tex_param->max_lod >= 1000.0f) ? 1e9f : tex_param->max_lod;

    id<MTLSamplerState> sampler = [_device newSamplerStateWithDescriptor:samplerDescriptor];
    if (!sampler) {
        NSLog(@"MGL SAMPLER ERROR: failed to create MTLSamplerState");
        return nil;
    }

    /* Diagnostic: log sampler state to diagnose Minecraft "gray + moiré" issues. */
    {
        static uint64_t s_samplerDiagLogs = 0;
        uint64_t diagHit = ++s_samplerDiagLogs;
        if (kMGLDiagnosticStateLogs &&
            (diagHit <= 64ull || (diagHit % 256ull) == 0ull)) {
            MGLTraceNSLog(@"MGL SAMPLER_DIAG minFilter=0x%x magFilter=0x%x mipFilter=%lu "
                          @"minLod=%f maxLod=%f lodMinClamp=%f lodMaxClamp=%f "
                          @"wrapS=0x%x wrapT=0x%x maxAniso=%f aniso=%d "
                          @"compareMode=0x%x compareFunc=0x%x hit=%llu",
                          (unsigned)tex_param->min_filter,
                          (unsigned)tex_param->mag_filter,
                          (unsigned long)samplerDescriptor.mipFilter,
                          tex_param->min_lod,
                          tex_param->max_lod,
                          samplerDescriptor.lodMinClamp,
                          samplerDescriptor.lodMaxClamp,
                          (unsigned)tex_param->wrap_s,
                          (unsigned)tex_param->wrap_t,
                          tex_param->max_anisotropy,
                          (int)samplerDescriptor.maxAnisotropy,
                          (unsigned)tex_param->compare_mode,
                          (unsigned)tex_param->compare_func,
                          (unsigned long long)diagHit);
        }
    }

    return sampler;
}

- (id<MTLTexture>)fallbackSampledTexture
{
    if (_fallbackSampledTexture || !kMGLEnableSampledTextureFallback) {
        return _fallbackSampledTexture;
    }

    MTLTextureDescriptor *desc =
        [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm
                                                           width:1
                                                          height:1
                                                       mipmapped:NO];
    desc.usage = MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModeShared;

    _fallbackSampledTexture = [_device newTextureWithDescriptor:desc];
    if (_fallbackSampledTexture) {
        uint32_t pixel = 0xff000000u;
        [_fallbackSampledTexture replaceRegion:MTLRegionMake2D(0, 0, 1, 1)
                                   mipmapLevel:0
                                     withBytes:&pixel
                                   bytesPerRow:sizeof(pixel)];
        NSLog(@"MGL INFO: Created 1x1 fallback sampled texture for missing shader resources");
    } else {
        NSLog(@"MGL ERROR: Failed to create fallback sampled texture");
    }

    return _fallbackSampledTexture;
}

- (id<MTLTexture>)fallbackCubeSampledTexture
{
    if (_fallbackCubeSampledTexture || !kMGLEnableSampledTextureFallback) {
        return _fallbackCubeSampledTexture;
    }

    MTLTextureDescriptor *desc = [MTLTextureDescriptor new];
    desc.textureType = MTLTextureTypeCube;
    desc.pixelFormat = MTLPixelFormatRGBA8Unorm;
    desc.width = 1;
    desc.height = 1;
    desc.depth = 1;
    desc.arrayLength = 1;
    desc.mipmapLevelCount = 1;
    desc.usage = MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModeShared;

    _fallbackCubeSampledTexture = [_device newTextureWithDescriptor:desc];
    if (_fallbackCubeSampledTexture) {
        uint32_t pixel = 0xff000000u;
        for (NSUInteger face = 0; face < 6; face++) {
            [_fallbackCubeSampledTexture replaceRegion:MTLRegionMake2D(0, 0, 1, 1)
                                           mipmapLevel:0
                                                 slice:face
                                             withBytes:&pixel
                                           bytesPerRow:sizeof(pixel)
                                         bytesPerImage:sizeof(pixel)];
        }
        NSLog(@"MGL INFO: Created 1x1 fallback cube sampled texture for missing shader resources");
    } else {
        NSLog(@"MGL ERROR: Failed to create fallback cube sampled texture");
    }

    return _fallbackCubeSampledTexture;
}

- (id<MTLTexture>)fallbackTextureBufferSampledTexture
{
    if (_fallbackSintTextureBuffer || !kMGLEnableSampledTextureFallback) {
        return _fallbackSintTextureBuffer;
    }

    static const NSUInteger kFallbackTexelCount = 64;
    static const NSUInteger kFallbackBytesPerTexel = 4;

    if (!_fallbackTextureBufferStorage) {
        _fallbackTextureBufferStorage = [_device newBufferWithLength:(kFallbackTexelCount * kFallbackBytesPerTexel)
                                                              options:MTLResourceStorageModeShared];
        if (_fallbackTextureBufferStorage && _fallbackTextureBufferStorage.contents) {
            memset(_fallbackTextureBufferStorage.contents, 0, kFallbackTexelCount * kFallbackBytesPerTexel);
        }
    }

    if (!_fallbackTextureBufferStorage) {
        NSLog(@"MGL ERROR: Failed to create fallback texture-buffer backing storage");
        return nil;
    }

    MTLTextureDescriptor *desc = [MTLTextureDescriptor new];
    desc.textureType = MTLTextureTypeTextureBuffer;
    desc.pixelFormat = MTLPixelFormatRGBA8Sint;
    desc.width = kFallbackTexelCount;
    desc.height = 1;
    desc.depth = 1;
    desc.mipmapLevelCount = 1;
    desc.usage = MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModeShared;

    @try {
        _fallbackSintTextureBuffer = [_fallbackTextureBufferStorage newTextureWithDescriptor:desc
                                                                                     offset:0
                                                                                bytesPerRow:(kFallbackTexelCount * kFallbackBytesPerTexel)];
    } @catch (NSException *exception) {
        NSLog(@"MGL ERROR: Failed to create fallback texture-buffer texture: %@", exception);
        _fallbackSintTextureBuffer = nil;
    }

    if (_fallbackSintTextureBuffer) {
        NSLog(@"MGL INFO: Created fallback signed integer texture buffer for missing/invalid texel-buffer resources");
    }

    return _fallbackSintTextureBuffer;
}

- (id<MTLTexture>)fallbackSampledTextureForExpectedType:(MTLTextureType)expectedType
                                               dataKind:(MGLTextureDataKind)dataKind
{
    if (!kMGLEnableSampledTextureFallback) {
        return nil;
    }

    MTLTextureType textureType = expectedType ? expectedType : MTLTextureType2D;
    if (textureType == MTLTextureTypeTextureBuffer) {
        return [self fallbackTextureBufferSampledTexture];
    }

    MTLPixelFormat pixelFormat = MTLPixelFormatRGBA8Unorm;
    if (dataKind == MGLTextureDataKindUint) {
        pixelFormat = MTLPixelFormatRGBA8Uint;
    } else if (dataKind == MGLTextureDataKindSint) {
        pixelFormat = MTLPixelFormatRGBA8Sint;
    } else if (dataKind == MGLTextureDataKindDepth) {
        pixelFormat = MTLPixelFormatDepth32Float;
    }

    if (!_fallbackSampledTextureCache) {
        _fallbackSampledTextureCache = [[NSMutableDictionary alloc] initWithCapacity:8];
    }

    NSUInteger keyValue = (((NSUInteger)textureType) << 8u) | ((NSUInteger)dataKind);
    NSNumber *key = @(keyValue);
    id<MTLTexture> cached = _fallbackSampledTextureCache[key];
    if (cached) {
        return cached;
    }

    MTLTextureDescriptor *desc = [MTLTextureDescriptor new];
    desc.textureType = textureType;
    desc.pixelFormat = pixelFormat;
    desc.width = 1;
    desc.height = 1;
    desc.depth = 1;
    desc.arrayLength = (textureType == MTLTextureTypeCube ||
                        textureType == MTLTextureTypeCubeArray ||
                        textureType == MTLTextureType2DArray ||
                        textureType == MTLTextureType1DArray ||
                        textureType == MTLTextureType2DMultisampleArray) ? 1 : 1;
    if (textureType == MTLTextureType2DMultisample ||
        textureType == MTLTextureType2DMultisampleArray) {
        desc.sampleCount = 2u;
    }
    desc.mipmapLevelCount = 1;
    desc.usage = MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModeShared;

    id<MTLTexture> texture = [_device newTextureWithDescriptor:desc];
    if (!texture) {
        NSLog(@"MGL ERROR: Failed to create %@ fallback sampled texture type=%lu format=%lu",
              [NSString stringWithUTF8String:mglTextureDataKindName(dataKind)],
              (unsigned long)textureType,
              (unsigned long)pixelFormat);
        return nil;
    }

    uint32_t pixel = dataKind == MGLTextureDataKindDepth ? 0u : 0xff000000u;
    MTLRegion region = textureType == MTLTextureType1D ||
                       textureType == MTLTextureType1DArray
        ? MTLRegionMake1D(0, 1)
        : MTLRegionMake2D(0, 0, 1, 1);
    if (textureType == MTLTextureTypeCube || textureType == MTLTextureTypeCubeArray) {
        NSUInteger sliceCount = (textureType == MTLTextureTypeCube) ? 6u : 6u;
        for (NSUInteger slice = 0; slice < sliceCount; slice++) {
            [texture replaceRegion:MTLRegionMake2D(0, 0, 1, 1)
                       mipmapLevel:0
                             slice:slice
                         withBytes:&pixel
                       bytesPerRow:sizeof(pixel)
                     bytesPerImage:sizeof(pixel)];
        }
    } else if (textureType == MTLTextureType1DArray ||
               textureType == MTLTextureType2DArray) {
        [texture replaceRegion:region
                   mipmapLevel:0
                         slice:0
                     withBytes:&pixel
                   bytesPerRow:sizeof(pixel)
                 bytesPerImage:sizeof(pixel)];
    } else {
        [texture replaceRegion:region
                   mipmapLevel:0
                     withBytes:&pixel
                   bytesPerRow:sizeof(pixel)];
    }

    _fallbackSampledTextureCache[key] = texture;
    NSLog(@"MGL INFO: Created %@ fallback sampled texture type=%lu format=%lu",
          [NSString stringWithUTF8String:mglTextureDataKindName(dataKind)],
          (unsigned long)textureType,
          (unsigned long)pixelFormat);

    return texture;
}

- (id<MTLSamplerState>)scaledBlitSamplerForFilter:(GLuint)filter
{
    BOOL wantsNearest = (filter == GL_NEAREST);
    id<MTLSamplerState> cached = wantsNearest ? _scaledBlitNearestSampler : _scaledBlitLinearSampler;
    if (cached) {
        return cached;
    }

    MTLSamplerDescriptor *desc = [[MTLSamplerDescriptor alloc] init];
    desc.minFilter = wantsNearest ? MTLSamplerMinMagFilterNearest : MTLSamplerMinMagFilterLinear;
    desc.magFilter = wantsNearest ? MTLSamplerMinMagFilterNearest : MTLSamplerMinMagFilterLinear;
    desc.mipFilter = MTLSamplerMipFilterNotMipmapped;
    desc.sAddressMode = MTLSamplerAddressModeClampToEdge;
    desc.tAddressMode = MTLSamplerAddressModeClampToEdge;
    desc.rAddressMode = MTLSamplerAddressModeClampToEdge;

    id<MTLSamplerState> sampler = [_device newSamplerStateWithDescriptor:desc];
    if (!sampler) {
        NSLog(@"MGL ERROR: failed to create scaled blit sampler filter=0x%x", filter);
        return nil;
    }

    if (wantsNearest) {
        _scaledBlitNearestSampler = sampler;
    } else {
        _scaledBlitLinearSampler = sampler;
    }

    return sampler;
}

- (id<MTLRenderPipelineState>)scaledBlitPipelineForPixelFormat:(MTLPixelFormat)pixelFormat
{
    if (pixelFormat == MTLPixelFormatInvalid || pixelFormat == 0) {
        pixelFormat = MTLPixelFormatBGRA8Unorm;
    }

    if (!_scaledBlitPipelineCache) {
        _scaledBlitPipelineCache = [[NSMutableDictionary alloc] initWithCapacity:4];
    }

    NSNumber *key = @((NSUInteger)pixelFormat);
    id<MTLRenderPipelineState> cached = _scaledBlitPipelineCache[key];
    if (cached) {
        return cached;
    }

    static NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct MGLScaledBlitParams { float4 uvRect; float forceOpaqueAlpha; float3 _padding; };\n"
         "struct MGLScaledBlitVOut { float4 position [[position]]; float2 uv; };\n"
         "vertex MGLScaledBlitVOut mgl_scaled_blit_vs(uint vid [[vertex_id]], constant MGLScaledBlitParams& p [[buffer(0)]]) {\n"
         "    float2 pos[4] = { float2(-1.0, -1.0), float2(1.0, -1.0), float2(-1.0, 1.0), float2(1.0, 1.0) };\n"
         "    float2 uv[4] = { float2(p.uvRect.x, p.uvRect.w), float2(p.uvRect.z, p.uvRect.w), float2(p.uvRect.x, p.uvRect.y), float2(p.uvRect.z, p.uvRect.y) };\n"
         "    MGLScaledBlitVOut o;\n"
         "    o.position = float4(pos[vid], 0.0, 1.0);\n"
         "    o.uv = uv[vid];\n"
         "    return o;\n"
         "}\n"
         "fragment float4 mgl_scaled_blit_fs(MGLScaledBlitVOut in [[stage_in]], constant MGLScaledBlitParams& p [[buffer(0)]], texture2d<float> src [[texture(0)]], sampler s [[sampler(0)]]) {\n"
         "    float4 color = src.sample(s, in.uv);\n"
         "    if (p.forceOpaqueAlpha > 0.5) { color.a = 1.0; }\n"
         "    return color;\n"
         "}\n";

    NSError *error = nil;
    id<MTLLibrary> library = [self newMetalLibraryWithSource:source
                                                     options:nil
                                                       label:@"MGL scaled blit"
                                                       error:&error];
    if (!library) {
        NSLog(@"MGL ERROR: scaled blit shader compile failed: %@", error);
        return nil;
    }

    id<MTLFunction> vs = [library newFunctionWithName:@"mgl_scaled_blit_vs"];
    id<MTLFunction> fs = [library newFunctionWithName:@"mgl_scaled_blit_fs"];
    if (!vs || !fs) {
        NSLog(@"MGL ERROR: scaled blit shader functions missing vs=%@ fs=%@", vs, fs);
        return nil;
    }

    MTLRenderPipelineDescriptor *desc = [[MTLRenderPipelineDescriptor alloc] init];
    desc.label = @"MGL scaled blit";
    desc.vertexFunction = vs;
    desc.fragmentFunction = fs;
    desc.colorAttachments[0].pixelFormat = pixelFormat;
    desc.rasterSampleCount = 1;
    mglEnableIndirectCommandBuffersForPipeline(desc);

    id<MTLRenderPipelineState> pipeline = [_device newRenderPipelineStateWithDescriptor:desc error:&error];
    if (!pipeline) {
        NSLog(@"MGL ERROR: scaled blit pipeline create failed pixelFormat=%lu error=%@",
              (unsigned long)pixelFormat,
              error);
        return nil;
    }

    _scaledBlitPipelineCache[key] = pipeline;
    NSLog(@"MGL INFO: created scaled blit pipeline pixelFormat=%lu", (unsigned long)pixelFormat);
    return pipeline;
}

- (id<MTLRenderPipelineState>)scaledDepthBlitPipelineForPixelFormat:(MTLPixelFormat)pixelFormat
{
    if (pixelFormat == MTLPixelFormatInvalid || pixelFormat == 0) {
        return nil;
    }

    if (!_scaledDepthBlitPipelineCache) {
        _scaledDepthBlitPipelineCache = [[NSMutableDictionary alloc] initWithCapacity:4];
    }

    NSNumber *key = @((NSUInteger)pixelFormat);
    id<MTLRenderPipelineState> cached = _scaledDepthBlitPipelineCache[key];
    if (cached) {
        return cached;
    }

    static NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct MGLScaledBlitParams { float4 uvRect; float forceOpaqueAlpha; float3 _padding; };\n"
         "struct MGLScaledBlitVOut { float4 position [[position]]; float2 uv; };\n"
         "struct MGLScaledDepthBlitFOut { float depth [[depth(any)]]; };\n"
         "vertex MGLScaledBlitVOut mgl_scaled_depth_blit_vs(uint vid [[vertex_id]], constant MGLScaledBlitParams& p [[buffer(0)]]) {\n"
         "    float2 pos[4] = { float2(-1.0, -1.0), float2(1.0, -1.0), float2(-1.0, 1.0), float2(1.0, 1.0) };\n"
         "    float2 uv[4] = { float2(p.uvRect.x, p.uvRect.w), float2(p.uvRect.z, p.uvRect.w), float2(p.uvRect.x, p.uvRect.y), float2(p.uvRect.z, p.uvRect.y) };\n"
         "    MGLScaledBlitVOut o;\n"
         "    o.position = float4(pos[vid], 0.0, 1.0);\n"
         "    o.uv = uv[vid];\n"
         "    return o;\n"
         "}\n"
         "fragment MGLScaledDepthBlitFOut mgl_scaled_depth_blit_fs(MGLScaledBlitVOut in [[stage_in]], depth2d<float> srcDepth [[texture(0)]], sampler s [[sampler(0)]]) {\n"
         "    MGLScaledDepthBlitFOut out;\n"
         "    out.depth = srcDepth.sample(s, in.uv);\n"
         "    return out;\n"
         "}\n";

    NSError *error = nil;
    id<MTLLibrary> library = [self newMetalLibraryWithSource:source
                                                     options:nil
                                                       label:@"MGL scaled depth blit"
                                                       error:&error];
    if (!library) {
        NSLog(@"MGL ERROR: scaled depth blit shader compile failed: %@", error);
        return nil;
    }

    id<MTLFunction> vs = [library newFunctionWithName:@"mgl_scaled_depth_blit_vs"];
    id<MTLFunction> fs = [library newFunctionWithName:@"mgl_scaled_depth_blit_fs"];
    if (!vs || !fs) {
        NSLog(@"MGL ERROR: scaled depth blit shader functions missing vs=%@ fs=%@", vs, fs);
        return nil;
    }

    MTLRenderPipelineDescriptor *desc = [[MTLRenderPipelineDescriptor alloc] init];
    desc.label = @"MGL scaled depth blit";
    desc.vertexFunction = vs;
    desc.fragmentFunction = fs;
    desc.depthAttachmentPixelFormat = pixelFormat;
    /* For packed depth+stencil formats, the stencil attachment pixel format
     * must also be set so Metal can match the render pass configuration
     * (which sets both depth and stencil attachments to the same texture). */
    if (mglMetalPixelFormatIsPackedDepthStencil(pixelFormat)) {
        desc.stencilAttachmentPixelFormat = pixelFormat;
    }
    desc.rasterSampleCount = 1;
    mglEnableIndirectCommandBuffersForPipeline(desc);

    id<MTLRenderPipelineState> pipeline = [_device newRenderPipelineStateWithDescriptor:desc error:&error];
    if (!pipeline) {
        NSLog(@"MGL ERROR: scaled depth blit pipeline create failed depthPixelFormat=%lu error=%@",
              (unsigned long)pixelFormat,
              error);
        return nil;
    }

    _scaledDepthBlitPipelineCache[key] = pipeline;
    NSLog(@"MGL INFO: created scaled depth blit pipeline depthPixelFormat=%lu", (unsigned long)pixelFormat);
    return pipeline;
}

- (id<MTLComputePipelineState>)msaaIntegerResolvePipelineForSigned:(BOOL)signedInteger
{
    if (!_msaaIntegerResolvePipelineCache) {
        _msaaIntegerResolvePipelineCache = [[NSMutableDictionary alloc] initWithCapacity:2];
    }

    NSNumber *key = @(signedInteger ? 1u : 0u);
    id<MTLComputePipelineState> cached = _msaaIntegerResolvePipelineCache[key];
    if (cached) {
        return cached;
    }

    NSString *entryName = signedInteger ? @"mgl_msaa_resolve_int" : @"mgl_msaa_resolve_uint";
    static NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct MGLMSAAIntegerResolveParams { uint2 srcOrigin; uint2 dstOrigin; uint2 size; uint2 _padding; };\n"
         "kernel void mgl_msaa_resolve_uint(texture2d_ms<uint, access::read> src [[texture(0)]], texture2d<uint, access::write> dst [[texture(1)]], constant MGLMSAAIntegerResolveParams& p [[buffer(0)]], uint2 gid [[thread_position_in_grid]]) {\n"
         "    if (gid.x >= p.size.x || gid.y >= p.size.y) return;\n"
         "    uint2 srcCoord = p.srcOrigin + gid;\n"
         "    uint2 dstCoord = p.dstOrigin + gid;\n"
         "    // GL requires GL_NEAREST for integer/MSAA blits; choose sample 0 deterministically.\n"
         "    dst.write(src.read(srcCoord, 0), dstCoord);\n"
         "}\n"
         "kernel void mgl_msaa_resolve_int(texture2d_ms<int, access::read> src [[texture(0)]], texture2d<int, access::write> dst [[texture(1)]], constant MGLMSAAIntegerResolveParams& p [[buffer(0)]], uint2 gid [[thread_position_in_grid]]) {\n"
         "    if (gid.x >= p.size.x || gid.y >= p.size.y) return;\n"
         "    uint2 srcCoord = p.srcOrigin + gid;\n"
         "    uint2 dstCoord = p.dstOrigin + gid;\n"
         "    // GL requires GL_NEAREST for integer/MSAA blits; choose sample 0 deterministically.\n"
         "    dst.write(src.read(srcCoord, 0), dstCoord);\n"
         "}\n";

    NSError *error = nil;
    id<MTLLibrary> library = [self newMetalLibraryWithSource:source
                                                     options:nil
                                                       label:@"MGL MSAA integer resolve"
                                                       error:&error];
    if (!library) {
        NSLog(@"MGL ERROR: MSAA integer resolve shader compile failed: %@", error);
        return nil;
    }

    id<MTLFunction> function = [library newFunctionWithName:entryName];
    if (!function) {
        NSLog(@"MGL ERROR: MSAA integer resolve shader function missing %@", entryName);
        return nil;
    }

    id<MTLComputePipelineState> pipeline = [_device newComputePipelineStateWithFunction:function
                                                                                 error:&error];
    if (!pipeline) {
        NSLog(@"MGL ERROR: MSAA integer resolve pipeline create failed signed=%d error=%@",
              signedInteger ? 1 : 0,
              error);
        return nil;
    }

    _msaaIntegerResolvePipelineCache[key] = pipeline;
    return pipeline;
}

- (BOOL)resolveIntegerMultisampleTexture:(id<MTLTexture>)sourceTexture
                               toTexture:(id<MTLTexture>)destTexture
                                srcOrigin:(MTLOrigin)srcOrigin
                                dstOrigin:(MTLOrigin)dstOrigin
                                     size:(MTLSize)size
                                   reason:(const char *)reason
{
    if (!sourceTexture || !destTexture ||
        sourceTexture.sampleCount <= 1u ||
        destTexture.sampleCount > 1u ||
        sourceTexture.pixelFormat != destTexture.pixelFormat ||
        !mglMetalPixelFormatIsIntegerColor(sourceTexture.pixelFormat) ||
        size.width == 0u || size.height == 0u) {
        return NO;
    }

    id<MTLComputePipelineState> pipeline =
        [self msaaIntegerResolvePipelineForSigned:mglMetalPixelFormatIsSignedIntegerColor(sourceTexture.pixelFormat)];
    if (!pipeline) {
        return NO;
    }

    if (![self ensureWritableCommandBuffer:"blitFramebuffer.msaaIntegerResolve"]) {
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return NO;
    }

    id<MTLComputeCommandEncoder> encoder = [_currentCommandBuffer computeCommandEncoder];
    if (!encoder) {
        NSLog(@"MGL WARN: failed to create MSAA integer resolve encoder for %s",
              reason ? reason : "unknown");
        return NO;
    }

    MGLMSAAIntegerResolveParams params;
    params.srcOrigin = (vector_uint2){(uint32_t)srcOrigin.x, (uint32_t)srcOrigin.y};
    params.dstOrigin = (vector_uint2){(uint32_t)dstOrigin.x, (uint32_t)dstOrigin.y};
    params.size = (vector_uint2){(uint32_t)size.width, (uint32_t)size.height};
    params._padding = (vector_uint2){0u, 0u};

    [encoder setComputePipelineState:pipeline];
    [encoder setTexture:sourceTexture atIndex:0];
    [encoder setTexture:destTexture atIndex:1];
    [encoder setBytes:&params length:sizeof(params) atIndex:0];

    MTLSize threads = MTLSizeMake(size.width, size.height, 1u);
    NSUInteger w = MIN((NSUInteger)16u, pipeline.maxTotalThreadsPerThreadgroup);
    NSUInteger h = MAX((NSUInteger)1u, MIN((NSUInteger)16u, pipeline.maxTotalThreadsPerThreadgroup / w));
    MTLSize threadgroup = MTLSizeMake(w, h, 1u);
    [encoder dispatchThreads:threads threadsPerThreadgroup:threadgroup];
    [encoder endEncoding];

    return YES;
}

- (id<MTLTexture>)resolvedReadbackTextureForMultisampleTexture:(id<MTLTexture>)sourceTexture
                                                   sourceLevel:(NSUInteger)sourceLevel
                                                   sourceSlice:(NSUInteger)sourceSlice
                                               sourceDepthPlane:(NSUInteger)sourceDepthPlane
                                                        reason:(const char *)reason
{
    if (!sourceTexture || sourceTexture.sampleCount <= 1u) {
        return sourceTexture;
    }

    if (sourceLevel != 0u ||
        sourceDepthPlane != 0u ||
        (sourceTexture.textureType != MTLTextureType2DMultisample &&
         sourceTexture.textureType != MTLTextureType2DMultisampleArray)) {
        NSLog(@"MGL WARNING: readPixels cannot resolve MSAA texture for %s level=%lu slice=%lu depth=%lu type=%lu",
              reason ? reason : "unknown",
              (unsigned long)sourceLevel,
              (unsigned long)sourceSlice,
              (unsigned long)sourceDepthPlane,
              (unsigned long)sourceTexture.textureType);
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return nil;
    }

    MTLTextureDescriptor *desc =
        [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:sourceTexture.pixelFormat
                                                          width:sourceTexture.width
                                                         height:sourceTexture.height
                                                      mipmapped:NO];
    desc.textureType = MTLTextureType2D;
    desc.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModePrivate;

    id<MTLTexture> resolvedTexture = [_device newTextureWithDescriptor:desc];
    if (!resolvedTexture) {
        NSLog(@"MGL WARNING: readPixels failed to allocate MSAA resolve texture for %s fmt=%lu size=%lux%lu samples=%lu",
              reason ? reason : "unknown",
              (unsigned long)sourceTexture.pixelFormat,
              (unsigned long)sourceTexture.width,
              (unsigned long)sourceTexture.height,
              (unsigned long)sourceTexture.sampleCount);
        mglDispatchError(ctx, __FUNCTION__, GL_OUT_OF_MEMORY);
        return nil;
    }

    if (![self ensureWritableCommandBuffer:"readPixels.msaaResolve"]) {
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return nil;
    }

    MTLRenderPassDescriptor *resolvePass = [MTLRenderPassDescriptor renderPassDescriptor];
    if (mglMetalPixelFormatIsDepthOrStencil(sourceTexture.pixelFormat)) {
        resolvePass.depthAttachment.texture = sourceTexture;
        resolvePass.depthAttachment.slice = sourceSlice;
        resolvePass.depthAttachment.level = sourceLevel;
        resolvePass.depthAttachment.depthPlane = sourceDepthPlane;
        resolvePass.depthAttachment.loadAction = MTLLoadActionLoad;
        resolvePass.depthAttachment.storeAction = MTLStoreActionMultisampleResolve;
        resolvePass.depthAttachment.resolveTexture = resolvedTexture;
        resolvePass.depthAttachment.resolveSlice = 0u;
        resolvePass.depthAttachment.resolveLevel = 0u;
        resolvePass.depthAttachment.resolveDepthPlane = 0u;
        resolvePass.depthAttachment.depthResolveFilter = MTLMultisampleDepthResolveFilterSample0;
    } else {
        resolvePass.colorAttachments[0].texture = sourceTexture;
        resolvePass.colorAttachments[0].slice = sourceSlice;
        resolvePass.colorAttachments[0].level = sourceLevel;
        resolvePass.colorAttachments[0].depthPlane = sourceDepthPlane;
        resolvePass.colorAttachments[0].loadAction = MTLLoadActionLoad;
        resolvePass.colorAttachments[0].storeAction = MTLStoreActionMultisampleResolve;
        resolvePass.colorAttachments[0].resolveTexture = resolvedTexture;
        resolvePass.colorAttachments[0].resolveSlice = 0u;
        resolvePass.colorAttachments[0].resolveLevel = 0u;
        resolvePass.colorAttachments[0].resolveDepthPlane = 0u;
    }

    id<MTLRenderCommandEncoder> resolveEncoder =
        [_currentCommandBuffer renderCommandEncoderWithDescriptor:resolvePass];
    if (!resolveEncoder) {
        NSLog(@"MGL WARNING: readPixels failed to create MSAA resolve encoder for %s",
              reason ? reason : "unknown");
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return nil;
    }
    [resolveEncoder endEncoding];

    return resolvedTexture;
}

- (id<MTLTexture>)depthFloatTextureForDepthStencilReadback:(id<MTLTexture>)sourceTexture
                                                    reason:(const char *)reason
{
    if (!sourceTexture ||
        sourceTexture.sampleCount > 1u ||
        !mglMetalPixelFormatIsPackedDepthStencil(sourceTexture.pixelFormat)) {
        return sourceTexture;
    }

    MTLTextureDescriptor *desc =
        [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatDepth32Float
                                                          width:sourceTexture.width
                                                         height:sourceTexture.height
                                                      mipmapped:NO];
    desc.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModePrivate;
    id<MTLTexture> depthTexture = [_device newTextureWithDescriptor:desc];
    if (!depthTexture) {
        mglDispatchError(ctx, __FUNCTION__, GL_OUT_OF_MEMORY);
        return nil;
    }

    id<MTLRenderPipelineState> pipeline =
        [self scaledDepthBlitPipelineForPixelFormat:MTLPixelFormatDepth32Float];
    id<MTLSamplerState> sampler = [self scaledBlitSamplerForFilter:GL_NEAREST];
    if (!pipeline || !sampler) {
        NSLog(@"MGL WARNING: readPixels DS depth extract unavailable for %s pipeline=%p sampler=%p",
              reason ? reason : "unknown",
              pipeline,
              sampler);
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return nil;
    }

    if (![self ensureWritableCommandBuffer:"readPixels.depthStencilExtract"]) {
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return nil;
    }

    MGLScaledBlitParams params;
    params.uvRect = (vector_float4){0.0f, 0.0f, 1.0f, 1.0f};
    params.forceOpaqueAlpha = 0.0f;
    params._padding = (vector_float3){0.0f, 0.0f, 0.0f};

    MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
    pass.depthAttachment.texture = depthTexture;
    pass.depthAttachment.loadAction = MTLLoadActionDontCare;
    pass.depthAttachment.storeAction = MTLStoreActionStore;

    id<MTLRenderCommandEncoder> encoder =
        [_currentCommandBuffer renderCommandEncoderWithDescriptor:pass];
    if (!encoder) {
        mglDispatchError(ctx, __FUNCTION__, GL_INVALID_OPERATION);
        return nil;
    }

    [encoder setRenderPipelineState:pipeline];
    [encoder setDepthStencilState:[self clearRectDepthState]];
    [encoder setVertexBytes:&params length:sizeof(params) atIndex:0];
    [encoder setFragmentBytes:&params length:sizeof(params) atIndex:0];
    [encoder setFragmentTexture:sourceTexture atIndex:0];
    [encoder setFragmentSamplerState:sampler atIndex:0];
    [encoder setViewport:(MTLViewport){
        .originX = 0.0,
        .originY = 0.0,
        .width = (double)sourceTexture.width,
        .height = (double)sourceTexture.height,
        .znear = 0.0,
        .zfar = 1.0
    }];
    [encoder drawPrimitives:MTLPrimitiveTypeTriangleStrip vertexStart:0 vertexCount:4];
    [encoder endEncoding];

    return depthTexture;
}

- (BOOL)textureCanUseGLSampledRenderTargetCopy:(Texture *)tex
                                        source:(id<MTLTexture>)source
{
    if (!tex || !source || !tex->is_render_target) {
        return NO;
    }

    if (tex->target != GL_TEXTURE_2D ||
        tex->width == 0u ||
        tex->height == 0u ||
        source.textureType != MTLTextureType2D ||
        source.mipmapLevelCount == 0u ||
        source.width == 0u ||
        source.height == 0u ||
        mglMetalPixelFormatIsDepthOrStencil(source.pixelFormat) ||
        mglTextureDataKindForPixelFormat(source.pixelFormat) != MGLTextureDataKindFloat) {
        return NO;
    }

    /* Apply sampled-copy protection to all 2D float render targets
     * regardless of size.  The previous size-based gating was a
     * Minecraft-specific heuristic that broke on larger render targets. */
    if (!mglTextureCanUseGLSampledRenderTargetCopy(tex)) {
        return NO;
    }

    return YES;
}

- (void)releaseGLSampledRenderTargetCopyForTexture:(Texture *)tex
{
    if (!tex) {
        return;
    }

    if (tex->mtl_gl_sampled_data) {
        mglSafeReleaseMetalObj((void **)&tex->mtl_gl_sampled_data);
    }

    tex->mtl_gl_sampled_width = 0u;
    tex->mtl_gl_sampled_height = 0u;
    tex->mtl_gl_sampled_format = 0u;
    tex->mtl_gl_sampled_levels = 0u;
    tex->mtl_gl_sampled_write_version = 0u;
}

/* Lazy refresh the Y-flipped sampled copy for `tex` if it is stale
 * (mtl_gl_sampled_write_version != mtl_render_target_write_version) and it
 * is safe to do so — i.e. the texture is NOT a color/depth attachment of
 * the currently-active render pass (Metal forbids reading a texture that
 * is being written in the same pass).
 *
 * UNUSED / DANGEROUS: callers inside bindTexturesToCurrentRenderEncoder
 * were removed because updateGLSampledRenderTargetCopyForTexture creates
 * its own renderCommandEncoder, which re-enters the Metal encoder during
 * a flush triggered by mglBindBufferRange and crashes AGX
 * (MTLReportFailure -> SIGABRT).  Retained as a helper in case a future
 * caller outside an active flush wants lazy refresh; it must never be
 * called from bindTexturesToCurrentRenderEncoder / processGLState /
 * flushDrawBuffer paths. */
- (BOOL)lazyRefreshGLSampledRenderTargetCopyForTexture:(Texture *)tex
                                                 stage:(const char *)stage
                                               program:(GLuint)programName
                                               binding:(GLuint)binding
                                                  unit:(GLuint)unit
{
    if (!tex || !tex->mtl_data) {
        return NO;
    }
    if (!mglTextureCanUseGLSampledRenderTargetCopy(tex)) {
        return NO;
    }
    if (tex->mtl_render_target_write_version == 0u) {
        return NO;
    }
    /* Already fresh — nothing to do. */
    if (tex->mtl_gl_sampled_data &&
        tex->mtl_gl_sampled_write_version == tex->mtl_render_target_write_version) {
        return YES;
    }
    /* Stale (or no copy yet): safe to refresh only if the texture is not an
     * attachment of the active render pass.  Reading a render-pass
     * attachment mid-pass is a Metal read-after-write hazard. */
    if (mglTextureIsAttachmentOfFramebuffer(_renderPassFramebuffer, tex)) {
        if (mglTraceLogIsEnabled()) {
            mglTraceLog("RT_SAMPLE_COPY_LAZY_SKIP stage=%s program=%u binding=%u unit=%u tex=%u writeVer=%u rtVer=%u reason=current-pass-attachment",
                        stage ? stage : "",
                        (unsigned)programName,
                        (unsigned)binding,
                        (unsigned)unit,
                        (unsigned)tex->name,
                        (unsigned)tex->mtl_gl_sampled_write_version,
                        (unsigned)tex->mtl_render_target_write_version);
        }
        return NO;
    }
    id<MTLTexture> source = (__bridge id<MTLTexture>)(tex->mtl_data);
    BOOL ok = [self updateGLSampledRenderTargetCopyForTexture:tex
                                                       source:source
                                                       reason:"lazy_sample_copy_refresh"];
    if (mglTraceLogIsEnabled()) {
        mglTraceLog("RT_SAMPLE_COPY_LAZY_REFRESH stage=%s program=%u binding=%u unit=%u tex=%u ok=%d writeVer=%u rtVer=%u",
                    stage ? stage : "",
                    (unsigned)programName,
                    (unsigned)binding,
                    (unsigned)unit,
                    (unsigned)tex->name,
                    ok ? 1 : 0,
                    (unsigned)tex->mtl_gl_sampled_write_version,
                    (unsigned)tex->mtl_render_target_write_version);
    }
    return ok && tex->mtl_gl_sampled_data &&
                tex->mtl_gl_sampled_write_version == tex->mtl_render_target_write_version;
}

- (id<MTLTexture>)freshGLSampledRenderTargetCopyForSampling:(Texture *)tex
                                                     source:(id<MTLTexture>)source
                                                      stage:(const char *)stage
                                                    program:(GLuint)programName
                                                    binding:(GLuint)binding
                                                       unit:(GLuint)unit
                                               expectedType:(MTLTextureType)expectedType
                                               expectedKind:(MGLTextureDataKind)expectedKind
{
    if (!tex || !source || !mglTextureCanUseGLSampledRenderTargetCopy(tex)) {
        return nil;
    }
    if (tex->mtl_render_target_write_version == 0u) {
        return nil;
    }

    id<MTLTexture> sampledCopy = tex->mtl_gl_sampled_data
        ? (__bridge id<MTLTexture>)(tex->mtl_gl_sampled_data)
        : nil;
    if (sampledCopy &&
        tex->mtl_gl_sampled_write_version == tex->mtl_render_target_write_version &&
        (expectedType == 0 || sampledCopy.textureType == expectedType) &&
        mglTexturePixelFormatCompatibleWithExpectedDataKind(sampledCopy.pixelFormat, expectedKind)) {
        return sampledCopy;
    }

    BOOL isFbAttachment = mglTextureIsAttachmentOfFramebuffer(_renderPassFramebuffer, tex);

    if ([self currentRenderPassUsesTexture:source] && !isFbAttachment) {
        /* The texture is used by the current render pass in a non-attachment
         * role (e.g. bound to another sampler).  We cannot safely end and
         * restore the pass in this case because the texture might be written
         * by the pass itself. */
        if (mglTraceLogIsEnabled()) {
            mglTraceLog("RT_SAMPLE_COPY_REPAIR_SKIP stage=%s program=%u binding=%u unit=%u tex=%u label=\"%s\" reason=current-pass-uses-texture writeVer=%u rtVer=%u",
                        stage ? stage : "",
                        (unsigned)programName,
                        (unsigned)binding,
                        (unsigned)unit,
                        (unsigned)tex->name,
                        mglTraceTextureLabel(tex),
                        (unsigned)tex->mtl_gl_sampled_write_version,
                        (unsigned)tex->mtl_render_target_write_version);
        }
        return nil;
    }

    /* If the texture is a color/depth attachment of the current framebuffer,
     * we CAN still repair: end the render pass (storeAction=Store preserves
     * the content), blit a copy, then restore the render pass with
     * loadAction=Load.  Previously this case returned nil, causing shaders
     * that sample from the FBO color attachment (e.g. Forge EarlyDisplay)
     * to read stale or undefined data — manifesting as missing UI elements. */
    if (isFbAttachment) {
        if (mglTraceLogIsEnabled()) {
            mglTraceLog("RT_SAMPLE_COPY_REPAIR_ATTEMPT stage=%s program=%u binding=%u unit=%u tex=%u label=\"%s\" reason=fb-attachment writeVer=%u rtVer=%u",
                        stage ? stage : "",
                        (unsigned)programName,
                        (unsigned)binding,
                        (unsigned)unit,
                        (unsigned)tex->name,
                        mglTraceTextureLabel(tex),
                        (unsigned)tex->mtl_gl_sampled_write_version,
                        (unsigned)tex->mtl_render_target_write_version);
        }
    }

    BOOL hadRenderEncoder = (_currentRenderEncoder != nil);
    if (hadRenderEncoder) {
        [self endRenderEncodingLocked];
    }

    sampledCopy = tex->mtl_gl_sampled_data
        ? (__bridge id<MTLTexture>)(tex->mtl_gl_sampled_data)
        : nil;
    if (!(sampledCopy &&
          tex->mtl_gl_sampled_write_version == tex->mtl_render_target_write_version &&
          (expectedType == 0 || sampledCopy.textureType == expectedType) &&
          mglTexturePixelFormatCompatibleWithExpectedDataKind(sampledCopy.pixelFormat, expectedKind))) {
        source = tex->mtl_data ? (__bridge id<MTLTexture>)(tex->mtl_data) : nil;
        if (source) {
            [self updateGLSampledRenderTargetCopyForTexture:tex
                                                     source:source
                                                     reason:"sample_gate_miss_repair"];
        }
        sampledCopy = tex->mtl_gl_sampled_data
            ? (__bridge id<MTLTexture>)(tex->mtl_gl_sampled_data)
            : nil;
    }

    if (hadRenderEncoder && !_currentRenderEncoder) {
        if (![self restoreRenderEncoderAfterTextureUploadForDraw:"sample_gate_miss_repair"]) {
            return nil;
        }
    }

    BOOL fresh =
        sampledCopy &&
        tex->mtl_gl_sampled_write_version == tex->mtl_render_target_write_version &&
        (expectedType == 0 || sampledCopy.textureType == expectedType) &&
        mglTexturePixelFormatCompatibleWithExpectedDataKind(sampledCopy.pixelFormat, expectedKind);
    if (mglTraceLogIsEnabled()) {
        mglTraceLog("RT_SAMPLE_COPY_REPAIR stage=%s program=%u binding=%u unit=%u tex=%u label=\"%s\" ok=%d copy=%p writeVer=%u rtVer=%u expectedType=%lu",
                    stage ? stage : "",
                    (unsigned)programName,
                    (unsigned)binding,
                    (unsigned)unit,
                    (unsigned)tex->name,
                    mglTraceTextureLabel(tex),
                    fresh ? 1 : 0,
                    sampledCopy,
                    (unsigned)tex->mtl_gl_sampled_write_version,
                    (unsigned)tex->mtl_render_target_write_version,
                    (unsigned long)expectedType);
    }
    return fresh ? sampledCopy : nil;
}

- (BOOL)updateGLSampledRenderTargetCopyForTexture:(Texture *)tex
                                           source:(id<MTLTexture>)source
                                           reason:(const char *)reason
{
    if (![self textureCanUseGLSampledRenderTargetCopy:tex source:source]) {
        return NO;
    }

    if (tex->mtl_render_target_write_version == 0u) {
        return NO;
    }

    NSUInteger copyLevelCount = 1u;
    if (source.mipmapLevelCount > 1u) {
        GLuint highestGLLevel = tex->num_levels > 0u ? tex->num_levels - 1u : 0u;
        if (tex->mipmap_levels > 0u && highestGLLevel >= tex->mipmap_levels) {
            highestGLLevel = tex->mipmap_levels - 1u;
        }

        GLuint maxParamLevel = tex->params.max_level;
        if (maxParamLevel != 1000u && maxParamLevel < highestGLLevel) {
            highestGLLevel = maxParamLevel;
        }

        NSUInteger highestSourceLevel = source.mipmapLevelCount - 1u;
        if (tex->params.base_level > highestGLLevel &&
            (NSUInteger)tex->params.base_level <= highestSourceLevel) {
            highestGLLevel = tex->params.base_level;
        }
        if ((NSUInteger)highestGLLevel > highestSourceLevel) {
            highestGLLevel = (GLuint)highestSourceLevel;
        }

        copyLevelCount = (NSUInteger)highestGLLevel + 1u;
    }

    if (tex->mtl_gl_sampled_data &&
        tex->mtl_gl_sampled_width == (GLuint)source.width &&
        tex->mtl_gl_sampled_height == (GLuint)source.height &&
        tex->mtl_gl_sampled_format == (GLuint)source.pixelFormat &&
        tex->mtl_gl_sampled_levels == (GLuint)copyLevelCount &&
        tex->mtl_gl_sampled_write_version == tex->mtl_render_target_write_version) {
        return YES;
    }

    BOOL needsNewCopy =
        tex->mtl_gl_sampled_data == NULL ||
        tex->mtl_gl_sampled_width != (GLuint)source.width ||
        tex->mtl_gl_sampled_height != (GLuint)source.height ||
        tex->mtl_gl_sampled_format != (GLuint)source.pixelFormat ||
        tex->mtl_gl_sampled_levels != (GLuint)copyLevelCount;
    if (needsNewCopy) {
        [self releaseGLSampledRenderTargetCopyForTexture:tex];

        /* Mirror the GL-visible mip window, not the whole Metal backing
         * allocation.  MC 1.21.11 can attach a render target with full mip
         * backing while sampling a view with MAX_LEVEL=0; copying every
         * backing level on each end_render_pass is needlessly expensive.
         * Mipmapped RT atlases that really expose levels 0..N still get an
         * N+1-level copy so textureLod / auto-mip sampling stay flipped. */
        BOOL copyMipmapped = (copyLevelCount > 1u);
        MTLTextureDescriptor *desc =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:source.pixelFormat
                                                               width:source.width
                                                              height:source.height
                                                           mipmapped:copyMipmapped];
        /* When mipmapped, Metal derives mipmapLevelCount from the dimensions
         * (e.g. 12 for a 2048x2048 texture).  Pin it to the GL copy window so
         * texture views keep absolute mip indices without forcing every
         * backing level through the Y-flip pass. */
        if (copyMipmapped) {
            desc.mipmapLevelCount = copyLevelCount;
        }
        desc.usage = MTLTextureUsageShaderRead | MTLTextureUsageRenderTarget;
        desc.storageMode = MTLStorageModePrivate;

        id<MTLTexture> copy = [_device newTextureWithDescriptor:desc];
        if (!copy) {
            static uint64_t s_copyCreateFailCount = 0;
            uint64_t hit = ++s_copyCreateFailCount;
            if (hit <= 32ull || (hit % 512ull) == 0ull) {
                NSLog(@"MGL RT-SAMPLE-COPY create failed tex=%u size=%lux%lu fmt=%lu reason=%s hit=%llu",
                      (unsigned)tex->name,
                      (unsigned long)source.width,
                      (unsigned long)source.height,
                      (unsigned long)source.pixelFormat,
                      reason ? reason : "(null)",
                      (unsigned long long)hit);
            }
            return NO;
        }

        tex->mtl_gl_sampled_data = (void *)CFBridgingRetain(copy);
        tex->mtl_gl_sampled_width = (GLuint)source.width;
        tex->mtl_gl_sampled_height = (GLuint)source.height;
        tex->mtl_gl_sampled_format = (GLuint)source.pixelFormat;
        tex->mtl_gl_sampled_levels = (GLuint)copyLevelCount;
    }

    id<MTLTexture> destination = (__bridge id<MTLTexture>)(tex->mtl_gl_sampled_data);
    id<MTLRenderPipelineState> pipeline = [self scaledBlitPipelineForPixelFormat:destination.pixelFormat];
    id<MTLSamplerState> sampler = [self scaledBlitSamplerForFilter:GL_NEAREST];
    if (!destination || !pipeline || !sampler) {
        static uint64_t s_copySetupFailCount = 0;
        uint64_t hit = ++s_copySetupFailCount;
        if (hit <= 32ull || (hit % 512ull) == 0ull) {
            NSLog(@"MGL RT-SAMPLE-COPY setup failed tex=%u dst=%p pipeline=%p sampler=%p reason=%s hit=%llu",
                  (unsigned)tex->name,
                  destination,
                  pipeline,
                  sampler,
                  reason ? reason : "(null)",
                  (unsigned long long)hit);
        }
        return NO;
    }

    if (![self ensureWritableCommandBuffer:reason ? reason : "rt_sample_copy"]) {
        return NO;
    }

    // Sampled render-target copy: flip rows once so that Metal row 0 (top, which
    // is what Metal's texture::sample sees at v=0) holds GL row 0 (bottom).
    //
    // Metal and GL disagree on the texture Y origin: Metal's clip space puts
    // gl_Position.y=+1 at the TOP (Metal row 0), and Metal's sampler reads v=0
    // at the TOP (row 0) too — so render and sample are internally consistent
    // in Metal and NO flip would be needed if a GL app sampled with v=0 meaning
    // "top".  But GL apps sample with v=0 meaning "bottom" (GL lower-left
    // origin), so a render target rendered by a GL shader then sampled by a GL
    // shader comes out Y-inverted: the GL sampler's "bottom" (v≈0) hits the
    // Metal "top" (row 0), which the GL renderer wrote at its "top".
    //
    // Flipping the copy once makes Metal row 0 hold the GL renderer's "bottom",
    // restoring GL sampling semantics for every consumer.  This applies to ALL
    // sampled 2D float render targets — the lightmap (16x16, sampled by
    // block.vsh's texture(Sampler2, UV2/256+0.5/16)), the screen/GUI targets
    // (sampled by the post chain), etc.
    //
    // The previous size-based gating (small RT -> "no flip", large RT -> "flip")
    // was a Minecraft-specific heuristic whose polarity was inverted relative to
    // its own comment: uvRect={0,1,1,0} (the "large RT" path) actually FLIPS
    // rows, and uvRect={0,0,1,1} (the "small RT" lightmap path) is IDENTITY —
    // so the lightmap was never flipped, inverting its brightness.  MC 1.21.8+
    // renders the lightmap on the GPU (so it's now a render target and hits
    // this path), which is why the symptom appears only there.
    //
    // uvRect={0,1,1,0} with the blit VS below:
    //   pos[0]=(-1,-1)[dest row 15] -> uv=(0,0)[src row 0, top]
    //   pos[2]=(-1,+1)[dest row 0]  -> uv=(0,1)[src row 15, bottom]
    // i.e. dest row 0 = src row 15 -> one row flip.
    BOOL yFlipCopy = YES;

    MGLScaledBlitParams params;
    params.uvRect = yFlipCopy
        ? (vector_float4){0.0f, 1.0f, 1.0f, 0.0f}
        : (vector_float4){0.0f, 0.0f, 1.0f, 1.0f};
    params.forceOpaqueAlpha = 0.0f;
    params._padding = (vector_float3){0.0f, 0.0f, 0.0f};

    /* Y-flip blit each mip level independently.  MC 1.21.11's terrain atlas
     * is a 5-level mipmapped RT whose mip 1-4 are NOT box-filtered downscales
     * of level 0 — they are independently rendered by the sprite-animation
     * pass (program 80) sampling a custom-mipped source atlas (986), so each
     * mip level carries distinct, MipmapStrategy-filtered content (important
     * for cutout alpha coverage on leaves etc.).  generateMipmapsForTexture
     * would box-filter the flipped level 0 and overwrite those custom mip
     * levels, corrupting them.  Instead, blit each source mip level into the
     * matching destination mip level with a Y-flipped uvRect, using level
     * views so the fragment shader's auto-mip sampler reads exactly the
     * intended source level. */
    NSUInteger mipLevels = MAX(copyLevelCount, 1u);
    if (mipLevels > destination.mipmapLevelCount) {
        mipLevels = destination.mipmapLevelCount;
    }
    if (mipLevels > (NSUInteger)source.mipmapLevelCount) {
        mipLevels = (NSUInteger)source.mipmapLevelCount;
    }
    for (NSUInteger lvl = 0u; lvl < mipLevels; lvl++) {
        @autoreleasepool {
            id<MTLTexture> srcLvl = source;
            id<MTLTexture> dstLvl = destination;
            if (mipLevels > 1u) {
                srcLvl = [source newTextureViewWithPixelFormat:source.pixelFormat
                                                   textureType:MTLTextureType2D
	                                                    levels:NSMakeRange(lvl, 1u)
	                                                    slices:NSMakeRange(0, 1u)];
                dstLvl = [destination newTextureViewWithPixelFormat:destination.pixelFormat
                                                        textureType:MTLTextureType2D
                                                             levels:NSMakeRange(lvl, 1u)
                                                             slices:NSMakeRange(0, 1u)];
                if (!srcLvl || !dstLvl) {
                    static uint64_t s_levelViewFailCount = 0;
                    uint64_t hit = ++s_levelViewFailCount;
                    if (hit <= 32ull || (hit % 512ull) == 0ull) {
                        NSLog(@"MGL RT-SAMPLE-COPY level view failed tex=%u lvl=%lu hit=%llu",
                              (unsigned)tex->name,
                              (unsigned long)lvl,
                              (unsigned long long)hit);
                    }
                    continue;
                }
            }

            MTLRenderPassDescriptor *copyPass = [MTLRenderPassDescriptor renderPassDescriptor];
            copyPass.colorAttachments[0].texture = dstLvl;
            copyPass.colorAttachments[0].level = 0u;
            copyPass.colorAttachments[0].loadAction = MTLLoadActionDontCare;
            copyPass.colorAttachments[0].storeAction = MTLStoreActionStore;
            copyPass.renderTargetWidth = dstLvl.width;
            copyPass.renderTargetHeight = dstLvl.height;

            id<MTLRenderCommandEncoder> copyEncoder = [_currentCommandBuffer renderCommandEncoderWithDescriptor:copyPass];
            if (!copyEncoder) {
                static uint64_t s_copyEncoderFailCount = 0;
                uint64_t hit = ++s_copyEncoderFailCount;
                if (hit <= 32ull || (hit % 512ull) == 0ull) {
                    NSLog(@"MGL RT-SAMPLE-COPY encoder failed tex=%u lvl=%lu reason=%s hit=%llu",
                          (unsigned)tex->name,
                          (unsigned long)lvl,
                          reason ? reason : "(null)",
                          (unsigned long long)hit);
                }
                continue;
            }

            [copyEncoder setRenderPipelineState:pipeline];
            [copyEncoder setVertexBytes:&params length:sizeof(params) atIndex:0];
            [copyEncoder setFragmentBytes:&params length:sizeof(params) atIndex:0];
            [copyEncoder setFragmentTexture:srcLvl atIndex:0];
            [copyEncoder setFragmentSamplerState:sampler atIndex:0];
            [copyEncoder setViewport:(MTLViewport){
                .originX = 0.0,
                .originY = 0.0,
                .width = (double)dstLvl.width,
                .height = (double)dstLvl.height,
                .znear = 0.0,
                .zfar = 1.0
            }];
            [copyEncoder setScissorRect:(MTLScissorRect){
                .x = 0,
                .y = 0,
                .width = dstLvl.width,
                .height = dstLvl.height
            }];
            [copyEncoder drawPrimitives:MTLPrimitiveTypeTriangleStrip vertexStart:0 vertexCount:4];
            [copyEncoder endEncoding];
        }
    }

    tex->mtl_gl_sampled_write_version = tex->mtl_render_target_write_version;

    if (mglTraceLogIsEnabled()) {
        mglTraceLog("RT_SAMPLE_COPY_UPDATED tex=%u label=\"%s\" lightmap=%d yFlip=%d src=%p dst=%p size=%lux%lu fmt=%lu srcLevels=%lu dstLevels=%lu glLevels=%u mips=%u base=%u max=%u writeVersion=%u reason=%s",
                    (unsigned)tex->name,
                    mglTraceTextureLabel(tex),
                    0,
                    yFlipCopy ? 1 : 0,
                    source,
                    destination,
                    (unsigned long)destination.width,
                    (unsigned long)destination.height,
                    (unsigned long)destination.pixelFormat,
                    (unsigned long)source.mipmapLevelCount,
                    (unsigned long)destination.mipmapLevelCount,
                    (unsigned)tex->num_levels,
                    (unsigned)tex->mipmap_levels,
                    (unsigned)tex->params.base_level,
                    (unsigned)tex->params.max_level,
                    (unsigned)tex->mtl_gl_sampled_write_version,
                    reason ? reason : "(null)");
    }

    return YES;
}

- (id<MTLRenderPipelineState>)clearRectPipelineForColorFormat:(MTLPixelFormat)colorFormat
                                                  depthFormat:(MTLPixelFormat)depthFormat
                                                  writesColor:(BOOL)writesColor
                                                  writesDepth:(BOOL)writesDepth
{
    if (!writesColor && !writesDepth) {
        return nil;
    }
    if (writesColor && colorFormat == MTLPixelFormatInvalid) {
        return nil;
    }
    if (writesDepth && depthFormat == MTLPixelFormatInvalid) {
        return nil;
    }

    if (!_clearRectPipelineCache) {
        _clearRectPipelineCache = [[NSMutableDictionary alloc] initWithCapacity:8];
    }

    NSString *key = [NSString stringWithFormat:@"%lu:%lu:%d:%d",
                     (unsigned long)colorFormat,
                     (unsigned long)depthFormat,
                     writesColor ? 1 : 0,
                     writesDepth ? 1 : 0];
    id<MTLRenderPipelineState> cached = _clearRectPipelineCache[key];
    if (cached) {
        return cached;
    }

    NSError *error = nil;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct MGLClearRectParams { float4 color; float depth; float3 _padding; };\n"
         "struct MGLClearRectVOut { float4 position [[position]]; };\n"
         "vertex MGLClearRectVOut mgl_clear_rect_vs(uint vid [[vertex_id]], constant MGLClearRectParams& p [[buffer(0)]]) {\n"
         "    float2 pos[4] = { float2(-1.0, -1.0), float2(1.0, -1.0), float2(-1.0, 1.0), float2(1.0, 1.0) };\n"
         "    MGLClearRectVOut o;\n"
         "    o.position = float4(pos[vid & 3u], p.depth, 1.0);\n"
         "    return o;\n"
         "}\n"
         "fragment float4 mgl_clear_rect_fs(MGLClearRectVOut in [[stage_in]], constant MGLClearRectParams& p [[buffer(0)]]) {\n"
         "    return p.color;\n"
         "}\n";

    id<MTLLibrary> library = [self newMetalLibraryWithSource:source
                                                     options:nil
                                                       label:@"MGL scissored clear"
                                                       error:&error];
    if (!library) {
        NSLog(@"MGL ERROR: scissored clear shader compile failed: %@", error);
        return nil;
    }

    id<MTLFunction> vs = [library newFunctionWithName:@"mgl_clear_rect_vs"];
    id<MTLFunction> fs = writesColor ? [library newFunctionWithName:@"mgl_clear_rect_fs"] : nil;
    if (!vs || (writesColor && !fs)) {
        NSLog(@"MGL ERROR: scissored clear shader functions missing vs=%@ fs=%@", vs, fs);
        return nil;
    }

    MTLRenderPipelineDescriptor *desc = [[MTLRenderPipelineDescriptor alloc] init];
    desc.label = @"MGL scissored clear";
    desc.vertexFunction = vs;
    desc.fragmentFunction = fs;
    desc.rasterSampleCount = 1;
    if (colorFormat != MTLPixelFormatInvalid) {
        desc.colorAttachments[0].pixelFormat = colorFormat;
        desc.colorAttachments[0].writeMask = writesColor ? MTLColorWriteMaskAll : MTLColorWriteMaskNone;
    }
    if (writesDepth) {
        desc.depthAttachmentPixelFormat = depthFormat;
    }
    mglEnableIndirectCommandBuffersForPipeline(desc);

    id<MTLRenderPipelineState> pipeline = [_device newRenderPipelineStateWithDescriptor:desc error:&error];
    if (!pipeline) {
        NSLog(@"MGL ERROR: scissored clear pipeline create failed color=%lu depth=%lu writesColor=%d writesDepth=%d error=%@",
              (unsigned long)colorFormat,
              (unsigned long)depthFormat,
              writesColor ? 1 : 0,
              writesDepth ? 1 : 0,
              error);
        return nil;
    }

    _clearRectPipelineCache[key] = pipeline;
    return pipeline;
}

- (id<MTLDepthStencilState>)clearRectDepthState
{
    if (_clearRectDepthState) {
        return _clearRectDepthState;
    }

    MTLDepthStencilDescriptor *desc = [[MTLDepthStencilDescriptor alloc] init];
    desc.depthCompareFunction = MTLCompareFunctionAlways;
    desc.depthWriteEnabled = YES;
    _clearRectDepthState = [_device newDepthStencilStateWithDescriptor:desc];
    return _clearRectDepthState;
}

- (id<MTLTexture>)fallbackSampledTextureForExpectedType:(MTLTextureType)expectedType
{
    if (expectedType == MTLTextureTypeCube) {
        return [self fallbackCubeSampledTexture];
    }
    if (expectedType == MTLTextureTypeTextureBuffer) {
        return [self fallbackTextureBufferSampledTexture];
    }

    return [self fallbackSampledTexture];
}

- (int)textureIndexForExpectedMetalType:(MTLTextureType)expectedType
{
    switch (expectedType) {
        case MTLTextureType1D:
            return _TEXTURE_1D;
        case MTLTextureType1DArray:
            return _TEXTURE_1D_ARRAY;
        case MTLTextureType2D:
            return _TEXTURE_2D;
        case MTLTextureType2DMultisample:
            return _TEXTURE_2D_MULTISAMPLE;
        case MTLTextureType2DArray:
            return _TEXTURE_2D_ARRAY;
        case MTLTextureType2DMultisampleArray:
            return _TEXTURE_2D_MULTISAMPLE_ARRAY;
        case MTLTextureType3D:
            return _TEXTURE_3D;
        case MTLTextureTypeCube:
            return _TEXTURE_CUBE_MAP;
        case MTLTextureTypeCubeArray:
            return _TEXTURE_CUBE_MAP_ARRAY;
        case MTLTextureTypeTextureBuffer:
            return _TEXTURE_BUFFER;
        default:
            return -1;
    }
}

- (GLuint)textureUnitForSampledResource:(SpirvResource *)sampledResource metalBinding:(GLuint)metalBinding stage:(int)stage
{
    Program *program = mglResolveProgramForStageFromState(ctx, stage);
    if (!program) {
        GLuint candidate = sampledResource &&
                           sampledResource->sampler_unit >= 0 &&
                           sampledResource->sampler_unit < TEXTURE_UNITS
            ? (GLuint)sampledResource->sampler_unit
            : metalBinding;
        return candidate;
    }

    const char *sampledName = NULL;
    if (!sampledResource && metalBinding < TEXTURE_UNITS) {
        sampledResource = mglFindSamplerResourceForMetalBinding(program, stage, metalBinding);
    }
    if (sampledResource) {
        sampledName = sampledResource->name;
    }

    /*
     * Minecraft usually assigns sampler texture units from the RenderPipeline
     * sampler list, not from numeric suffixes like Sampler2. For example, chunk
     * rendering declares Sampler0 and Sampler2, so Sampler2 can be uploaded
     * through glUniform1i(..., 1). Keep sampler units on the exact reflected
     * resource instead of only the Metal binding: vertex and fragment resources
     * commonly share binding numbers, and binding-level state can make entity,
     * hand, and text textures bleed into each other.
     */
    if (sampledResource &&
        sampledResource->sampler_unit_explicit &&
        sampledResource->sampler_unit >= 0 &&
        sampledResource->sampler_unit < TEXTURE_UNITS) {
        return (GLuint)sampledResource->sampler_unit;
    }

    if (metalBinding >= TEXTURE_UNITS) {
        return metalBinding;
    }

    bool stageExplicit = (stage >= 0 && stage < _MAX_SHADER_TYPES)
        ? (program->sampler_units_explicit_by_stage[stage][metalBinding] == GL_TRUE)
        : false;
    bool globalExplicit = (program->sampler_units_explicit[metalBinding] == GL_TRUE);

    GLint unit = (stage >= 0 && stage < _MAX_SHADER_TYPES)
        ? program->sampler_units_by_stage[stage][metalBinding]
        : program->sampler_units[metalBinding];

    if (stageExplicit && unit >= 0 && unit < TEXTURE_UNITS) {
        return (GLuint)unit;
    }

    unit = program->sampler_units[metalBinding];
    if (globalExplicit && unit >= 0 && unit < TEXTURE_UNITS) {
        return (GLuint)unit;
    }

    GLint defaultUnit = (stage >= 0 && stage < _MAX_SHADER_TYPES)
        ? program->sampler_units_by_stage[stage][metalBinding]
        : program->sampler_units[metalBinding];
    if (defaultUnit < 0 || defaultUnit >= TEXTURE_UNITS) {
        defaultUnit = program->sampler_units[metalBinding];
    }

    if (sampledResource &&
        !sampledResource->sampler_unit_explicit &&
        sampledResource->sampler_unit >= 0 &&
        sampledResource->sampler_unit < TEXTURE_UNITS) {
        return (GLuint)sampledResource->sampler_unit;
    }

    if (defaultUnit >= 0 && defaultUnit < TEXTURE_UNITS) {
        return (GLuint)defaultUnit;
    }

    /*
     * OpenGL's valid default is unit 0, and explicit glUniform1i uploads above
     * are authoritative. No name-based fallback is applied.
     */
    return 0u;
}

- (GLuint)textureUnitForSampledBinding:(GLuint)metalBinding stage:(int)stage
{
    return [self textureUnitForSampledResource:NULL metalBinding:metalBinding stage:stage];
}

- (Texture *)textureForSampledResource:(SpirvResource *)sampledResource
                          metalBinding:(GLuint)metalBinding
                                  stage:(int)stage
                           expectedType:(MTLTextureType)expectedType
{
    if (!ctx || metalBinding >= TEXTURE_UNITS) {
        return NULL;
    }

    GLuint textureUnit = [self textureUnitForSampledResource:sampledResource
                                                metalBinding:metalBinding
                                                       stage:stage];
    if (textureUnit >= TEXTURE_UNITS) {
        return NULL;
    }

    if (expectedType == 0) {
        return STATE(active_textures[textureUnit]);
    }

    int textureIndex = [self textureIndexForExpectedMetalType:expectedType];
    if (textureIndex >= 0 && textureIndex < _MAX_TEXTURE_TYPES) {
        Texture *typedTexture = STATE(texture_units[textureUnit].textures[textureIndex]);
        /* SPIRV-Cross lowers sampler1D to texture2d in MSL, so expectedType is
         * MTLTextureType2D even for GL_TEXTURE_1D bindings. If the _TEXTURE_2D
         * slot only contains an auto-created default texture (name ==
         * TEX_OBJ_RES_NAME) while the unit's active texture is a real
         * GL_TEXTURE_1D, prefer the 1D texture. Otherwise the default 2D
         * texture leaks across test cases and masks the real 1D binding. */
        if (typedTexture && typedTexture->name == TEX_OBJ_RES_NAME) {
            Texture *activeTexture = STATE(active_textures[textureUnit]);
            if (activeTexture && activeTexture->name != TEX_OBJ_RES_NAME) {
                typedTexture = NULL;
            }
        }
        if (typedTexture) {
            return typedTexture;
        }

        if (expectedType == MTLTextureType2D) {
            Texture *activeTexture = STATE(active_textures[textureUnit]);
            if (activeTexture &&
                activeTexture->target == GL_TEXTURE_1D) {
                return activeTexture;
            }
        }

        // Texel-buffer resources must not silently fall back to GL_TEXTURE_2D.
        // Minecraft's CloudFaces is declared as SpvDimBuffer but SPIRV-Cross
        // lowers it to a 1-row texture2d<int> in MSL. If no GL_TEXTURE_BUFFER
        // is bound, using the active 2D atlas here feeds float/RGBA data into a
        // signed integer vertex resource and corrupts the whole frame.
        if (expectedType == MTLTextureTypeTextureBuffer) {
            static uint64_t s_missingTextureBufferBindingLogs = 0;
            uint64_t hit = ++s_missingTextureBufferBindingLogs;
            if (hit <= 32ull || (hit % 512ull) == 0ull) {
                Texture *activeTexture = STATE(active_textures[textureUnit]);
                NSLog(@"MGL TEXBUFFER BIND MISSING binding=%u unit=%u activeTex=%u activeTarget=0x%x hit=%llu",
                      (unsigned)metalBinding,
                      (unsigned)textureUnit,
                      activeTexture ? (unsigned)activeTexture->name : 0u,
                      activeTexture ? (unsigned)activeTexture->target : 0u,
                      (unsigned long long)hit);
            }
            return NULL;
        }

        /*
         * OpenGL texture units keep one binding per texture target. A sampler2D
         * samples the GL_TEXTURE_2D slot for its unit, even if a cubemap or texel
         * buffer was bound more recently on that same unit. Falling back to the
         * unit's "active" texture here lets sky cubemaps and buffer textures bleed
         * into item/entity shaders when Minecraft switches pipelines.
         */
        static uint64_t s_missingTypedTextureBindingLogs = 0;
        uint64_t hit = ++s_missingTypedTextureBindingLogs;
        if (hit <= 64ull || (hit % 512ull) == 0ull) {
            Texture *activeTexture = STATE(active_textures[textureUnit]);
            NSLog(@"MGL TEX TYPED BIND MISSING binding=%u stage=%s unit=%u expectedType=%lu expectedIndex=%d activeTex=%u activeTarget=0x%x hit=%llu",
                  (unsigned)metalBinding,
                  mglShaderStageName(stage),
                  (unsigned)textureUnit,
                  (unsigned long)expectedType,
                  textureIndex,
                  activeTexture ? (unsigned)activeTexture->name : 0u,
                  activeTexture ? (unsigned)activeTexture->target : 0u,
                  (unsigned long long)hit);
        }
        return NULL;
    }

    return STATE(active_textures[textureUnit]);
}

- (Texture *)textureForSampledBinding:(GLuint)metalBinding stage:(int)stage expectedType:(MTLTextureType)expectedType
{
    return [self textureForSampledResource:NULL
                              metalBinding:metalBinding
                                      stage:stage
                               expectedType:expectedType];
}

- (id<MTLSamplerState>)fallbackSamplerState
{
    if (_fallbackSamplerState) {
        return _fallbackSamplerState;
    }

    MTLSamplerDescriptor *desc = [MTLSamplerDescriptor new];
    desc.minFilter = MTLSamplerMinMagFilterNearest;
    desc.magFilter = MTLSamplerMinMagFilterNearest;
    desc.mipFilter = MTLSamplerMipFilterNotMipmapped;
    desc.sAddressMode = MTLSamplerAddressModeClampToEdge;
    desc.tAddressMode = MTLSamplerAddressModeClampToEdge;
    desc.rAddressMode = MTLSamplerAddressModeClampToEdge;

    _fallbackSamplerState = [_device newSamplerStateWithDescriptor:desc];
    if (!_fallbackSamplerState) {
        NSLog(@"MGL ERROR: Failed to create fallback sampler state");
    }

    return _fallbackSamplerState;
}

- (void)traceSampledTextureReadback:(id<MTLTexture>)texture
                              glTex:(Texture *)glTex
                              level:(TextureLevel *)level0
                            program:(GLuint)program
                            binding:(GLuint)binding
                              stage:(NSString *)stage
                             reason:(NSString *)reason
                                hit:(uint64_t)hit
{
    if (!texture || !_device || !_commandQueue) {
        return;
    }

    MTLPixelFormat fmt = texture.pixelFormat;
    BOOL fourByteColor =
        fmt == MTLPixelFormatRGBA8Unorm ||
        fmt == MTLPixelFormatRGBA8Unorm_sRGB ||
        fmt == MTLPixelFormatBGRA8Unorm ||
        fmt == MTLPixelFormatBGRA8Unorm_sRGB;
    if (!fourByteColor) {
        MGLTraceNSLog(@"MGL TRACE sampled.readback skip program=%u binding=%u glTex=%u reason=%@ fmt=%lu type=%lu size=%lux%lu hit=%llu",
              (unsigned)program,
              (unsigned)binding,
              glTex ? (unsigned)glTex->name : 0u,
              reason,
              (unsigned long)fmt,
              (unsigned long)texture.textureType,
              (unsigned long)texture.width,
              (unsigned long)texture.height,
              (unsigned long long)hit);
        return;
    }

    NSUInteger texWidth = (NSUInteger)texture.width;
    NSUInteger texHeight = (NSUInteger)texture.height;
    if (texWidth == 0 || texHeight == 0) {
        return;
    }

    NSUInteger sampleWidth = MIN(texWidth, 8u);
    NSUInteger sampleHeight = MIN(texHeight, 8u);
    NSUInteger bytesPerPixel = 4u;
    NSUInteger bytesPerRow = sampleWidth * bytesPerPixel;
    NSUInteger byteCount = bytesPerRow * sampleHeight;
    if (byteCount == 0) {
        return;
    }

    id<MTLBuffer> readback = [_device newBufferWithLength:byteCount
                                                  options:MTLResourceStorageModeShared];
    id<MTLCommandBuffer> cb = [_commandQueue commandBuffer];
    id<MTLBlitCommandEncoder> blit = cb ? [cb blitCommandEncoder] : nil;
    if (!readback || !cb || !blit) {
        MGLTraceNSLog(@"MGL TRACE sampled.readback setup-fail program=%u binding=%u glTex=%u reason=%@ readback=%p cb=%p blit=%p hit=%llu",
              (unsigned)program,
              (unsigned)binding,
              glTex ? (unsigned)glTex->name : 0u,
              reason,
              readback,
              cb,
              blit,
              (unsigned long long)hit);
        return;
    }

    [blit copyFromTexture:texture
              sourceSlice:0
              sourceLevel:0
             sourceOrigin:MTLOriginMake(0, 0, 0)
               sourceSize:MTLSizeMake(sampleWidth, sampleHeight, 1)
                 toBuffer:readback
        destinationOffset:0
   destinationBytesPerRow:bytesPerRow
 destinationBytesPerImage:byteCount];
    [blit endEncoding];
    [cb commit];
    [cb waitUntilCompleted];

    const uint8_t *p = (const uint8_t *)readback.contents;
    uint64_t byteSum = 0;
    NSUInteger nonZeroBytes = 0;
    uint32_t firstPixel = 0;
    uint32_t pixelXor = 0;
    uint32_t minPixel = UINT32_MAX;
    uint32_t maxPixel = 0;
    NSUInteger pixelCount = byteCount / sizeof(uint32_t);

    if (p) {
        for (NSUInteger i = 0; i < byteCount; i++) {
            byteSum += (uint64_t)p[i];
            if (p[i] != 0) {
                nonZeroBytes++;
            }
        }
        if (byteCount >= sizeof(firstPixel)) {
            memcpy(&firstPixel, p, sizeof(firstPixel));
        }
        for (NSUInteger i = 0; i < pixelCount; i++) {
            uint32_t pixel = 0;
            memcpy(&pixel, p + (i * sizeof(pixel)), sizeof(pixel));
            pixelXor ^= pixel;
            if (pixel < minPixel) {
                minPixel = pixel;
            }
            if (pixel > maxPixel) {
                maxPixel = pixel;
            }
        }
    }

    MGLTraceNSLog(@"MGL TRACE sampled.readback stage=%@ program=%u binding=%u glTex=%u reason=%@ hit=%llu "
          "mtl=%p fmt=%lu type=%lu size=%lux%lu sample=%lux%lu status=%s error=%@ "
          "nonZero=%lu/%lu sum=%llu first=0x%08x min=0x%08x max=0x%08x xor=0x%08x "
          "level(init ever=%u full=%u zero=%u source=%u upload=%lu src=%p hash=0x%016llx)",
          stage,
          (unsigned)program,
          (unsigned)binding,
          glTex ? (unsigned)glTex->name : 0u,
          reason,
          (unsigned long long)hit,
          texture,
          (unsigned long)fmt,
          (unsigned long)texture.textureType,
          (unsigned long)texWidth,
          (unsigned long)texHeight,
          (unsigned long)sampleWidth,
          (unsigned long)sampleHeight,
          mglCommandBufferStatusName(cb.status),
          cb.error,
          (unsigned long)nonZeroBytes,
          (unsigned long)byteCount,
          (unsigned long long)byteSum,
          firstPixel,
          minPixel == UINT32_MAX ? 0u : minPixel,
          maxPixel,
          pixelXor,
          level0 ? (unsigned)level0->ever_written : 0u,
          level0 ? (unsigned)level0->has_initialized_data : 0u,
          level0 ? (unsigned)level0->suspicious_zero_upload : 0u,
          level0 ? (unsigned)level0->last_init_source : 0u,
          (unsigned long)(level0 ? level0->last_upload_size : 0u),
          level0 ? (void *)level0->last_src_ptr : NULL,
          (unsigned long long)(level0 ? level0->last_src_hash : 0ull));
}

/*
 * GL_TEXTURE_BASE_LEVEL selects the lowest mipmap level used for sampling.
 * Metal textures always start at level 0, so when base_level > 0 a texture
 * view is created whose level 0 corresponds to the GL base_level.  This lets
 * the Metal sampler's lodMinClamp/lodMaxClamp operate in the same coordinate
 * space as GL (relative to base_level).  GL_TEXTURE_MAX_LEVEL caps the
 * highest level.  When base_level == 0 the original texture is returned
 * unchanged so the common case has no overhead.
 */
/* mglSampledTextureViewForBaseLevel now lives in mgl_texture_compat.m — see
 * mgl_texture_compat.h. */

- (bool) bindTexturesToCurrentRenderEncoder
{
    static const NSUInteger kMaxFragmentSamplerSlots = 16;
    static uint64_t s_bindTexturesCallCount = 0;
    uint64_t bindCall = ++s_bindTexturesCallCount;
    bool traceBind = mglShouldTraceCall(bindCall);
    GLuint vertexSampledCount = 0;
    GLuint vertexBoundTextures = 0;
    GLuint vertexFallbackTextures = 0;
    GLuint boundSampledTextures = 0;
    GLuint nilSampledTextures = 0;
    GLuint fallbackSampledTextures = 0;
    GLuint boundSampledSamplers = 0;
    Program *vertexProgram = NULL;
    Program *fragmentProgram = NULL;
    GLuint vertexProgramName = 0u;
    GLuint fragmentProgramName = 0u;

    if (!_currentRenderEncoder) {
        // No active render encoder yet (or it was rotated). Texture/sampler binding
        // can be deferred until the next encoder is created.
        return true;
    }

    /*
     * This array is the per-draw sampler snapshot used later by replay logging
     * and by the RT-sampled-copy cull bypass decision.  Do not let bindings from
     * the previous program survive in slots the current program does not touch.
     */
    if (mglTraceLogIsEnabled()) {
        mglTraceFragmentTextureTraceBindings("CLEAR",
                                             "bind_textures_begin",
                                             _fragmentTextureTraceBindings,
                                             TEXTURE_UNITS,
                                             ctx ? mglCurrentRenderProgramKey(ctx) : 0u,
                                             _pipelineProgramName);
    }
    memset(_fragmentTextureTraceBindings, 0, sizeof(_fragmentTextureTraceBindings));

#define MGL_ABORT_TBIND_IF_ENCODER_CLOSED() do { \
    if (!_currentRenderEncoder) { \
        if (ctx) { \
            ctx->state.dirty_bits |= (DIRTY_TEX | DIRTY_TEX_BINDING | DIRTY_RENDER_STATE); \
        } \
        return false; \
    } \
} while (0)

    vertexProgram = mglResolveProgramForStageFromState(ctx, _VERTEX_SHADER);
    fragmentProgram = mglResolveProgramForStageFromState(ctx, _FRAGMENT_SHADER);
    vertexProgramName = vertexProgram ? vertexProgram->name : mglCurrentRenderProgramKey(ctx);
    fragmentProgramName = fragmentProgram ? fragmentProgram->name : mglCurrentRenderProgramKey(ctx);

    id<MTLSamplerState> defaultSampler = [self fallbackSamplerState];
    if (defaultSampler) {
        NSUInteger warmupCount = TEXTURE_UNITS;
        if (warmupCount > kMaxFragmentSamplerSlots) {
            warmupCount = kMaxFragmentSamplerSlots;
        }
        for (NSUInteger s = 0; s < warmupCount; s++) {
            [self setVertexSamplerStateIfNeeded:defaultSampler atIndex:s];
            [self setFragmentSamplerStateIfNeeded:defaultSampler atIndex:s];
        }
    }

    // Metal validates every active stage resource. Bind vertex-stage sampled
    // images as well, even though most Minecraft pipelines only sample in FS.
    vertexSampledCount = [self getProgramBindingCount:_VERTEX_SHADER type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE];
    for (GLuint i = 0; i < vertexSampledCount; i++)
    {
        GLuint spirvBinding = [self getProgramBinding:_VERTEX_SHADER type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE index:(int)i];
        GLuint glBinding = [self getProgramGLBinding:_VERTEX_SHADER type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE index:(int)i];
        if (spirvBinding >= TEXTURE_UNITS || glBinding >= TEXTURE_UNITS) {
            continue;
        }
        Program *currentProgram = vertexProgram;
        SpirvResource *sampledResource = NULL;
        const char *sampledName = "";
        if (currentProgram &&
            i < currentProgram->spirv_resources_list[_VERTEX_SHADER][SPVC_RESOURCE_TYPE_SAMPLED_IMAGE].count) {
            sampledResource = &currentProgram->spirv_resources_list[_VERTEX_SHADER][SPVC_RESOURCE_TYPE_SAMPLED_IMAGE].list[i];
            sampledName = sampledResource->name;
        }
        if (mglShouldSkipStageTextureResource(currentProgram,
                                              _VERTEX_SHADER,
                                              SPVC_RESOURCE_TYPE_SAMPLED_IMAGE,
                                              sampledResource)) {
            continue;
        }
        GLuint textureUnit = [self textureUnitForSampledResource:sampledResource
                                                    metalBinding:spirvBinding
                                                           stage:_VERTEX_SHADER];
        MTLTextureType expectedType = [self getProgramExpectedTextureType:_VERTEX_SHADER
                                                                      type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE
                                                                     index:(int)i];
        MTLTextureType lookupType = [self getProgramDeclaredTextureType:_VERTEX_SHADER
                                                                    type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE
                                                                   index:(int)i];
        MGLTextureDataKind expectedKind = [self getProgramExpectedTextureDataKind:_VERTEX_SHADER
                                                                             type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE
                                                                            index:(int)i];
        Texture *ptr = [self textureForSampledResource:sampledResource
                                          metalBinding:spirvBinding
                                                  stage:_VERTEX_SHADER
                                           expectedType:(lookupType ? lookupType : expectedType)];
        id<MTLTexture> texture = nil;
        id<MTLSamplerState> sampler = defaultSampler;
        BOOL usedTypeFallback = NO;

        if (ptr) {
            RETURN_FALSE_ON_FAILURE([self bindMTLTexture:ptr]);
            MGL_ABORT_TBIND_IF_ENCODER_CLOSED();
            if (ptr->mtl_data) {
                texture = (__bridge id<MTLTexture>)(ptr->mtl_data);
                texture = mglSampledTextureViewForBaseLevel(ptr, texture);
            }
            if (texture && expectedType != 0 && texture.textureType != expectedType) {
                static uint64_t s_vertexTypeMismatchLogCount = 0;
                uint64_t hit = ++s_vertexTypeMismatchLogCount;
                if (hit <= 32ull || (hit % 512ull) == 0ull) {
                    NSLog(@"MGL TEX TYPE MISMATCH vertex binding=%u program=%u glTex=%u glTarget=0x%x mtlType=%lu expected=%lu hit=%llu",
                          (unsigned)spirvBinding,
                          (unsigned)vertexProgramName,
                          (unsigned)ptr->name,
                          (unsigned)ptr->target,
                          (unsigned long)texture.textureType,
                          (unsigned long)expectedType,
                          (unsigned long long)hit);
                }
                Program *dumpProgram = currentProgram;
                mglWriteProgramMSLDump(dumpProgram,
                                       [NSString stringWithFormat:@"tex-type-mismatch-vertex-binding-%u", spirvBinding]);
                texture = [self fallbackSampledTextureForExpectedType:expectedType dataKind:expectedKind];
                usedTypeFallback = YES;
            }
            if (texture &&
                !mglTexturePixelFormatCompatibleWithExpectedDataKind(texture.pixelFormat, expectedKind)) {
                static uint64_t s_vertexDataKindMismatchLogCount = 0;
                uint64_t hit = ++s_vertexDataKindMismatchLogCount;
                if (hit <= 32ull || (hit % 512ull) == 0ull) {
                    NSLog(@"MGL TEX DATA MISMATCH vertex binding=%u program=%u glTex=%u glTarget=0x%x format=%lu actualKind=%s expectedKind=%s expectedType=%lu hit=%llu",
                          (unsigned)spirvBinding,
                          (unsigned)vertexProgramName,
                          (unsigned)ptr->name,
                          (unsigned)ptr->target,
                          (unsigned long)texture.pixelFormat,
                          mglTextureDataKindName(mglTextureDataKindForPixelFormat(texture.pixelFormat)),
                          mglTextureDataKindName(expectedKind),
                          (unsigned long)expectedType,
                          (unsigned long long)hit);
                }
                Program *dumpProgram = currentProgram;
                mglWriteProgramMSLDump(dumpProgram,
                                       [NSString stringWithFormat:@"tex-data-mismatch-vertex-binding-%u", spirvBinding]);
                texture = [self fallbackSampledTextureForExpectedType:expectedType dataKind:expectedKind];
                usedTypeFallback = YES;
            }

            if (textureUnit < TEXTURE_UNITS && STATE(texture_samplers[textureUnit])) {
                Sampler *glSampler = STATE(texture_samplers[textureUnit]);
                if (glSampler->dirty_bits && glSampler->mtl_data) {
                    mglSafeReleaseMetalObj((void **)&glSampler->mtl_data);
                }
                if (glSampler->mtl_data == NULL) {
                    glSampler->mtl_data = (void *)CFBridgingRetain([self createMTLSamplerForTexParam:&glSampler->params target:ptr->target]);
                    glSampler->dirty_bits = 0;
                }
                sampler = (__bridge id<MTLSamplerState>)(glSampler->mtl_data);
                mglTraceLogExternal("VERT_SAMPLER_RESOLVE program=%u binding=%u unit=%u source=glSampler samplerName=%u minFilter=0x%x magFilter=0x%x wrapS=0x%x wrapT=0x%x minLod=%.3f maxLod=%.3f glTex=%u base=%u max=%u texSize=%ux%u boundSize=%lux%lu boundLevels=%lu",
                                    (unsigned)vertexProgramName,
                                    (unsigned)spirvBinding,
                                    (unsigned)textureUnit,
                                    (unsigned)glSampler->name,
                                    (unsigned)glSampler->params.min_filter,
                                    (unsigned)glSampler->params.mag_filter,
                                    (unsigned)glSampler->params.wrap_s,
                                    (unsigned)glSampler->params.wrap_t,
                                    (double)glSampler->params.min_lod,
                                    (double)glSampler->params.max_lod,
                                    (unsigned)ptr->name,
                                    (unsigned)ptr->params.base_level,
                                    (unsigned)ptr->params.max_level,
                                    (unsigned)ptr->width,
                                    (unsigned)ptr->height,
                                    (unsigned long)(texture ? texture.width : 0u),
                                    (unsigned long)(texture ? texture.height : 0u),
                                    (unsigned long)(texture ? texture.mipmapLevelCount : 0u));
            } else if (ptr->params.mtl_data) {
                sampler = (__bridge id<MTLSamplerState>)(ptr->params.mtl_data);
                mglTraceLogExternal("VERT_SAMPLER_RESOLVE program=%u binding=%u unit=%u source=texParamsFallback samplerName=0 minFilter=0x%x magFilter=0x%x wrapS=0x%x wrapT=0x%x minLod=%.3f maxLod=%.3f glTex=%u base=%u max=%u texSize=%ux%u boundSize=%lux%lu boundLevels=%lu",
                                    (unsigned)vertexProgramName,
                                    (unsigned)spirvBinding,
                                    (unsigned)textureUnit,
                                    (unsigned)ptr->params.min_filter,
                                    (unsigned)ptr->params.mag_filter,
                                    (unsigned)ptr->params.wrap_s,
                                    (unsigned)ptr->params.wrap_t,
                                    (double)ptr->params.min_lod,
                                    (double)ptr->params.max_lod,
                                    (unsigned)ptr->name,
                                    (unsigned)ptr->params.base_level,
                                    (unsigned)ptr->params.max_level,
                                    (unsigned)ptr->width,
                                    (unsigned)ptr->height,
                                    (unsigned long)(texture ? texture.width : 0u),
                                    (unsigned long)(texture ? texture.height : 0u),
                                    (unsigned long)(texture ? texture.mipmapLevelCount : 0u));
            }
        }

        /* Y-Flip Subsystem: unified decision for sampling a render target.
         *
         * NOTE: lazy refresh from bindTexturesToCurrentRenderEncoder was
         * removed — it re-enters the Metal render encoder during a flush and
         * crashes AGX.  See the fragment counterpart above. */
        if (!usedTypeFallback && ptr && ptr->is_render_target) {
            MGLYFlipDecision yflip = mglDecideYFlipForSampledRT(ptr, currentProgram);
            if (mglTraceRTYFlipDiagnosticsEnabled()) {
                mglTraceLog("RT_YFLIP_DECISION stage=vertex program=%u name=%s binding=%u unit=%u tex=%u label=\"%s\" decision=%s(%d) authority=0x%x rtVer=%u copyVer=%u hasCopy=%d sampleYFlip=%d",
                            (unsigned)vertexProgramName,
                            sampledName ? sampledName : "",
                            (unsigned)spirvBinding,
                            (unsigned)textureUnit,
                            (unsigned)ptr->name,
                            mglTraceTextureLabel(ptr),
                            mglYFlipDecisionName(yflip),
                            (int)yflip,
                            (unsigned)ptr->mtl_render_yflip_authority,
                            (unsigned)ptr->mtl_render_target_write_version,
                            (unsigned)ptr->mtl_gl_sampled_write_version,
                            ptr->mtl_gl_sampled_data ? 1 : 0,
                            mglProgramHasExistingFramebufferSampleYFlip(currentProgram) ? 1 : 0);
            }

            if (yflip == MGL_YFLIP_USE_SAMPLED_COPY) {
                BOOL boundSampledCopy = NO;
                if (ptr->mtl_gl_sampled_data &&
                    ptr->mtl_gl_sampled_write_version == ptr->mtl_render_target_write_version &&
                    mglTextureCanUseGLSampledRenderTargetCopy(ptr)) {
                    id<MTLTexture> sampledCopy = (__bridge id<MTLTexture>)(ptr->mtl_gl_sampled_data);
                    if (sampledCopy &&
                        (expectedType == 0 || sampledCopy.textureType == expectedType) &&
                        mglTexturePixelFormatCompatibleWithExpectedDataKind(sampledCopy.pixelFormat, expectedKind)) {
                        if (mglTraceLogIsEnabled()) {
                            mglTraceLog("RT_SAMPLE_COPY_BIND stage=vertex program=%u name=%s binding=%u unit=%u tex=%u label=\"%s\" original=%p copy=%p size=%lux%lu originalLevels=%lu copyLevels=%lu glLevels=%u mips=%u base=%u max=%u version=%u",
                                        (unsigned)vertexProgramName,
                                        sampledName ? sampledName : "",
                                        (unsigned)spirvBinding,
                                        (unsigned)textureUnit,
                                        (unsigned)ptr->name,
                                        mglTraceTextureLabel(ptr),
                                        texture,
                                        sampledCopy,
                                        (unsigned long)sampledCopy.width,
                                        (unsigned long)sampledCopy.height,
                                        (unsigned long)(texture ? texture.mipmapLevelCount : 0u),
                                        (unsigned long)sampledCopy.mipmapLevelCount,
                                        (unsigned)ptr->num_levels,
                                        (unsigned)ptr->mipmap_levels,
                                        (unsigned)ptr->params.base_level,
                                        (unsigned)ptr->params.max_level,
                                        (unsigned)ptr->mtl_gl_sampled_write_version);
                        }
                        texture = mglSampledTextureViewForBaseLevel(ptr, sampledCopy);
                        boundSampledCopy = YES;
                    }
                }
                if (!boundSampledCopy && mglTextureCanUseGLSampledRenderTargetCopy(ptr)) {
                    id<MTLTexture> repairedCopy =
                        [self freshGLSampledRenderTargetCopyForSampling:ptr
                                                                  source:texture
                                                                   stage:"vertex"
                                                                 program:vertexProgramName
                                                                 binding:spirvBinding
                                                                    unit:textureUnit
                                                            expectedType:expectedType
                                                            expectedKind:expectedKind];
                    if (repairedCopy) {
                        return false;
                    }
                }
                if (!boundSampledCopy && ptr->mtl_gl_sampled_data &&
                    !mglTextureCanUseGLSampledRenderTargetCopy(ptr)) {
                    mglLogSkippedGLSampledRenderTargetCopy(ctx,
                                                           currentProgram,
                                                           ptr,
                                                           "vertex",
                                                           sampledName,
                                                           spirvBinding,
                                                           textureUnit,
                                                           "target-gate");
                } else if (!boundSampledCopy && mglTraceLogIsEnabled()) {
                    BOOL hasCopy = (ptr->mtl_gl_sampled_data != NULL);
                    BOOL verMatch = (ptr->mtl_gl_sampled_write_version == ptr->mtl_render_target_write_version);
                    BOOL canUse = mglTextureCanUseGLSampledRenderTargetCopy(ptr);
                    mglTraceLog("RT_SAMPLE_COPY_GATE_MISS stage=vertex program=%u name=%s binding=%u unit=%u tex=%u label=\"%s\" isRT=%d hasCopy=%d verMatch=%d writeVer=%u rtVer=%u canUse=%d expectedType=%lu",
                                (unsigned)vertexProgramName,
                                sampledName ? sampledName : "",
                                (unsigned)spirvBinding,
                                (unsigned)textureUnit,
                                (unsigned)ptr->name,
                                mglTraceTextureLabel(ptr),
                                1, hasCopy ? 1 : 0, verMatch ? 1 : 0,
                                (unsigned)ptr->mtl_gl_sampled_write_version,
                                (unsigned)ptr->mtl_render_target_write_version,
                                canUse ? 1 : 0,
                                (unsigned long)expectedType);
                }
            } else {
                /* MGL_YFLIP_USE_ORIGINAL or MGL_YFLIP_USE_ORIGINAL_AND_INJECT:
                 * keep the original texture; no copy needed. */
                static uint64_t s_vertexRTSampleCopySkipExistingFlipLogCount = 0;
                uint64_t hit = ++s_vertexRTSampleCopySkipExistingFlipLogCount;
                if (mglTraceLogIsEnabled() && (hit <= 32ull || (hit % 512ull) == 0ull)) {
                    mglTraceLog("RT_SAMPLE_COPY_SKIP_EXISTING_YFLIP hit=%llu stage=vertex program=%u name=%s binding=%u tex=%u label=\"%s\" decision=%s(%d)",
                                (unsigned long long)hit,
                                (unsigned)vertexProgramName,
                                sampledName ? sampledName : "",
                                (unsigned)spirvBinding,
                                (unsigned)(ptr ? ptr->name : 0u),
                                mglTraceTextureLabel(ptr),
                                mglYFlipDecisionName(yflip),
                                (int)yflip);
                }
            }
        }

        if (!texture) {
            texture = [self fallbackSampledTextureForExpectedType:expectedType dataKind:expectedKind];
            if (texture) {
                vertexFallbackTextures++;
                static uint64_t s_vertexFallbackLogCount = 0;
                uint64_t hit = ++s_vertexFallbackLogCount;
                if (hit <= 32ull || (hit % 512ull) == 0ull) {
                    NSLog(@"MGL TEX FALLBACK vertex sampled binding=%u program=%u name=%s unit=%u glTex=%u kind=%s size=%lux%lu hit=%llu",
                          (unsigned)spirvBinding,
                          (unsigned)vertexProgramName,
                          sampledName ? sampledName : "",
                          (unsigned)textureUnit,
                          ptr ? (unsigned)ptr->name : 0u,
                          "generic",
                          (unsigned long)texture.width,
                          (unsigned long)texture.height,
                          (unsigned long long)hit);
                }
            }
        }

        [self setVertexTextureIfNeeded:texture atIndex:spirvBinding];
        if (sampler && spirvBinding < kMaxFragmentSamplerSlots) {
            [self setVertexSamplerStateIfNeeded:sampler atIndex:spirvBinding];
        }
        Program *focusedTextureProgram = currentProgram;
        if (mglProgramNeedsBindingTrace(focusedTextureProgram)) {
            static uint64_t s_focusedVertexTextureBindLogs = 0;
            if (mglShouldLogFocusedBinding(&s_focusedVertexTextureBindLogs)) {
                TextureLevel *level0 = mglTraceTextureBaseLevel(ptr);
                NSLog(@"MGL TBIND focused stage=vertex program=%u resource=%s metalTextureSlot=%u samplerUnit=%u glTex=%u target=0x%x mtl=%p mtlType=%lu size=%lux%lu level0=%ux%u init(ever=%u full=%u source=%u)",
                      (unsigned)focusedTextureProgram->name,
                      sampledName ? sampledName : "",
                      (unsigned)spirvBinding,
                      (unsigned)textureUnit,
                      ptr ? (unsigned)ptr->name : 0u,
                      ptr ? (unsigned)ptr->target : 0u,
                      texture,
                      (unsigned long)(texture ? texture.textureType : 0),
                      (unsigned long)(texture ? texture.width : 0),
                      (unsigned long)(texture ? texture.height : 0),
                      level0 ? (unsigned)level0->width : 0u,
                      level0 ? (unsigned)level0->height : 0u,
                      level0 ? (unsigned)level0->ever_written : 0u,
                      level0 ? (unsigned)level0->has_initialized_data : 0u,
                      level0 ? (unsigned)level0->last_init_source : 0u);
            }
        }
        static uint64_t s_traceFileVertexTextureBindLogs = 0;
        if (mglProgramNeedsTraceLog(focusedTextureProgram) &&
            mglShouldLogTraceFileBindingForProgram(focusedTextureProgram, &s_traceFileVertexTextureBindLogs)) {
            TextureLevel *level0 = mglTraceTextureBaseLevel(ptr);
            int expectedIndex = [self textureIndexForExpectedMetalType:(lookupType ? lookupType : expectedType)];
            Texture *unitActive = textureUnit < TEXTURE_UNITS ? STATE(active_textures[textureUnit]) : NULL;
            Texture *unitExpected = (textureUnit < TEXTURE_UNITS &&
                                     expectedIndex >= 0 &&
                                     expectedIndex < _MAX_TEXTURE_TYPES)
                ? STATE(texture_units[textureUnit].textures[expectedIndex])
                : NULL;
            Texture *unit2D = textureUnit < TEXTURE_UNITS ? STATE(texture_units[textureUnit].textures[_TEXTURE_2D]) : NULL;
            Texture *unitCube = textureUnit < TEXTURE_UNITS ? STATE(texture_units[textureUnit].textures[_TEXTURE_CUBE_MAP]) : NULL;
            mglTraceLog("TBIND stage=vertex program=%u resource=%s metalTextureSlot=%u samplerUnit=%u resUnit=%d explicit=%d glTex=%u target=0x%x fallback=%d expectedType=%lu lookupType=%lu expectedIndex=%d unit(active=%u expected=%u tex2D=%u cube=%u) mtl=%p mtlType=%lu size=%lux%lu level0=%ux%u init(ever=%u full=%u source=%u)",
                        (unsigned)focusedTextureProgram->name,
                        sampledName ? sampledName : "",
                        (unsigned)spirvBinding,
                        (unsigned)textureUnit,
                        sampledResource ? (int)sampledResource->sampler_unit : -1,
                        (sampledResource && sampledResource->sampler_unit_explicit) ? 1 : 0,
                        ptr ? (unsigned)ptr->name : 0u,
                        ptr ? (unsigned)ptr->target : 0u,
                        usedTypeFallback ? 1 : 0,
                        (unsigned long)expectedType,
                        (unsigned long)lookupType,
                        expectedIndex,
                        mglTraceTextureName(unitActive),
                        mglTraceTextureName(unitExpected),
                        mglTraceTextureName(unit2D),
                        mglTraceTextureName(unitCube),
                        texture,
                        (unsigned long)(texture ? texture.textureType : 0),
                        (unsigned long)(texture ? texture.width : 0),
                        (unsigned long)(texture ? texture.height : 0),
                        level0 ? (unsigned)level0->width : 0u,
                        level0 ? (unsigned)level0->height : 0u,
                        level0 ? (unsigned)level0->ever_written : 0u,
                        level0 ? (unsigned)level0->has_initialized_data : 0u,
                        level0 ? (unsigned)level0->last_init_source : 0u);
        }
        if (ptr && ptr->target == GL_TEXTURE_BUFFER) {
            static uint64_t s_vertexTexelBufferBindLogs = 0;
            uint64_t hit = ++s_vertexTexelBufferBindLogs;
            if (hit <= 32ull || (hit % 512ull) == 0ull) {
                Texture *unitActive = textureUnit < TEXTURE_UNITS ? STATE(active_textures[textureUnit]) : NULL;
                Texture *unitBuffer = textureUnit < TEXTURE_UNITS ? STATE(texture_units[textureUnit].textures[_TEXTURE_BUFFER_TARGET]) : NULL;
                NSLog(@"MGL TEXBUFFER BIND vertex hit=%llu program=%u binding=%u unit=%u ptrTex=%u active=%u bufferSlot=%u expectedType=%lu lookupType=%lu mtlTex=%p mtlType=%lu size=%lux%lu format=%lu sampler=%p",
                      (unsigned long long)hit,
                      (unsigned)vertexProgramName,
                      (unsigned)spirvBinding,
                      (unsigned)textureUnit,
                      (unsigned)ptr->name,
                      mglTraceTextureName(unitActive),
                      mglTraceTextureName(unitBuffer),
                      (unsigned long)expectedType,
                      (unsigned long)lookupType,
                      texture,
                      (unsigned long)(texture ? texture.textureType : 0),
                      (unsigned long)(texture ? texture.width : 0),
                      (unsigned long)(texture ? texture.height : 0),
                      (unsigned long)(texture ? texture.pixelFormat : 0),
                      sampler);
            }
        }
        if (ptr && ptr->target != GL_TEXTURE_BUFFER) {
            Program *sampleProgram = currentProgram;
            GLuint sampleProgramName = sampleProgram ? sampleProgram->name : vertexProgramName;
            TextureLevel *sampleLevel0 = mglTraceTextureBaseLevel(ptr);
            BOOL focusedVertexSample =
                (sampleProgramName == 34u) ||
                (sampleLevel0 &&
                 (sampleLevel0->suspicious_zero_upload ||
                  !sampleLevel0->ever_written ||
                  !sampleLevel0->has_initialized_data));
            if (focusedVertexSample) {
                static uint64_t s_vertexSampleDetailLogCount = 0;
                uint64_t hit = ++s_vertexSampleDetailLogCount;
                if (hit <= 128ull || (hit % 512ull) == 0ull) {
                    int expectedIndex = [self textureIndexForExpectedMetalType:expectedType];
                    Texture *unitActive = textureUnit < TEXTURE_UNITS ? STATE(active_textures[textureUnit]) : NULL;
                    Texture *unitExpected = (expectedIndex >= 0 && expectedIndex < _MAX_TEXTURE_TYPES)
                        ? STATE(texture_units[textureUnit].textures[expectedIndex])
                        : NULL;
                    uint64_t levelDataHash = (sampleLevel0 && sampleLevel0->data && sampleLevel0->data_size > 0)
                        ? mglTraceHashBytes((const void *)(uintptr_t)sampleLevel0->data, sampleLevel0->data_size)
                        : 0ull;

                    MGLTraceNSLog(@"MGL TRACE texbind.sample-detail call=%llu hit=%llu stage=vertex program=%u name=%s binding=%u "
                          "unit=%u expectedType=%lu expectedIndex=%d ptrTex=%u ptr=%p target=0x%x fallback=%d mtlTex=%p mtlType=%lu mtlSize=%lux%lu "
                          "unit(active=%u expected=%u) "
                          "l0=%ux%ux%u bytes=%lu init(ever=%u full=%u zero=%u source=%u upload=%lu src=%p hash=0x%016llx dataHash=0x%016llx)",
                          (unsigned long long)bindCall,
                          (unsigned long long)hit,
                          sampleProgramName,
                          sampledName ? sampledName : "",
                          (unsigned)spirvBinding,
                          (unsigned)textureUnit,
                          (unsigned long)expectedType,
                          expectedIndex,
                          mglTraceTextureName(ptr),
                          ptr,
                          ptr ? (unsigned)ptr->target : 0u,
                          usedTypeFallback ? 1 : 0,
                          texture,
                          (unsigned long)(texture ? texture.textureType : 0),
                          (unsigned long)(texture ? texture.width : 0),
                          (unsigned long)(texture ? texture.height : 0),
                          mglTraceTextureName(unitActive),
                          mglTraceTextureName(unitExpected),
                          sampleLevel0 ? (unsigned)sampleLevel0->width : 0u,
                          sampleLevel0 ? (unsigned)sampleLevel0->height : 0u,
                          sampleLevel0 ? (unsigned)sampleLevel0->depth : 0u,
                          (unsigned long)(sampleLevel0 ? sampleLevel0->data_size : 0u),
                          sampleLevel0 ? (unsigned)sampleLevel0->ever_written : 0u,
                          sampleLevel0 ? (unsigned)sampleLevel0->has_initialized_data : 0u,
                          sampleLevel0 ? (unsigned)sampleLevel0->suspicious_zero_upload : 0u,
                          sampleLevel0 ? (unsigned)sampleLevel0->last_init_source : 0u,
                          (unsigned long)(sampleLevel0 ? sampleLevel0->last_upload_size : 0u),
                          sampleLevel0 ? (void *)sampleLevel0->last_src_ptr : NULL,
                          (unsigned long long)(sampleLevel0 ? sampleLevel0->last_src_hash : 0ull),
                          (unsigned long long)levelDataHash);
                }
            }
        }
        if (texture) {
            vertexBoundTextures++;
            if (usedTypeFallback) {
                vertexFallbackTextures++;
            }
        }
    }

    // Bind sampled images (texture + sampler).
    GLuint sampledCount = [self getProgramBindingCount:_FRAGMENT_SHADER type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE];
    for (GLuint i = 0; i < sampledCount; i++)
    {
        GLuint spirvBinding = [self getProgramBinding:_FRAGMENT_SHADER type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE index:(int)i];
        GLuint glBinding = [self getProgramGLBinding:_FRAGMENT_SHADER type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE index:(int)i];
        if (spirvBinding >= TEXTURE_UNITS || glBinding >= TEXTURE_UNITS) {
            continue;
        }
        Program *sampleProgram = fragmentProgram;
        SpirvResource *sampledResource = NULL;
        const char *sampledName = "";
        if (sampleProgram &&
            i < sampleProgram->spirv_resources_list[_FRAGMENT_SHADER][SPVC_RESOURCE_TYPE_SAMPLED_IMAGE].count) {
            sampledResource = &sampleProgram->spirv_resources_list[_FRAGMENT_SHADER][SPVC_RESOURCE_TYPE_SAMPLED_IMAGE].list[i];
            sampledName = sampledResource->name;
        }
        if (mglShouldSkipStageTextureResource(sampleProgram,
                                              _FRAGMENT_SHADER,
                                              SPVC_RESOURCE_TYPE_SAMPLED_IMAGE,
                                              sampledResource)) {
            continue;
        }
        GLuint textureUnit = [self textureUnitForSampledResource:sampledResource
                                                    metalBinding:spirvBinding
                                                           stage:_FRAGMENT_SHADER];

        MTLTextureType expectedType = [self getProgramExpectedTextureType:_FRAGMENT_SHADER
                                                                      type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE
                                                                     index:(int)i];
        MTLTextureType lookupType = [self getProgramDeclaredTextureType:_FRAGMENT_SHADER
                                                                    type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE
                                                                   index:(int)i];
        MGLTextureDataKind expectedKind = [self getProgramExpectedTextureDataKind:_FRAGMENT_SHADER
                                                                             type:SPVC_RESOURCE_TYPE_SAMPLED_IMAGE
                                                                            index:(int)i];
        Texture *ptr = [self textureForSampledResource:sampledResource
                                          metalBinding:spirvBinding
                                                  stage:_FRAGMENT_SHADER
                                           expectedType:(lookupType ? lookupType : expectedType)];
        id<MTLTexture> texture = nil;
        id<MTLSamplerState> sampler = nil;
        id<MTLTexture> directTextureForTrace = nil;
        id<MTLTexture> sampledCopyForTrace = nil;
        BOOL usedFallbackTexture = NO;
        BOOL suppressMissingTextureFallback = NO;
        BOOL usedSampledCopyForTrace = NO;

        if (ptr) {
            RETURN_FALSE_ON_FAILURE([self bindMTLTexture:ptr]);
            MGL_ABORT_TBIND_IF_ENCODER_CLOSED();
            if (ptr->mtl_data) {
                texture = (__bridge id<MTLTexture>)(ptr->mtl_data);
                texture = mglSampledTextureViewForBaseLevel(ptr, texture);
            }
            BOOL sampledNameIsInSampler =
                sampledName && strcmp(sampledName, "InSampler") == 0;
            if (texture &&
                sampledNameIsInSampler &&
                mglMetalPixelFormatIsDepthOrStencil(texture.pixelFormat)) {
                GLuint pairedFboName = 0u;
                Texture *pairedColor =
                    mglFindFramebufferColorTexturePairedWithDepth(ctx, ptr, &pairedFboName);
                Texture *recoverTexture = NULL;
                id<MTLTexture> recoverMTL = nil;
                const char *recoverReason = "none";
                BOOL recoveredFromSampledCopy = NO;
                BOOL recoveredFromPreviousVersion = NO;
                NSUInteger recoverAttachmentIndex = MAX_COLOR_ATTACHMENTS;
                NSUInteger currentAttachmentIndex = MAX_COLOR_ATTACHMENTS;
                BOOL pairedColorIsCurrentDrawTarget =
                    mglCurrentDrawFramebufferUsesColorTexture(ctx,
                                                              pairedColor,
                                                              pairedFboName,
                                                              &currentAttachmentIndex);
                id<MTLTexture> pairedMTL = nil;

                if (pairedColor) {
                    RETURN_FALSE_ON_FAILURE([self bindMTLTexture:pairedColor]);
                    MGL_ABORT_TBIND_IF_ENCODER_CLOSED();
                    pairedMTL = pairedColor->mtl_data
                        ? (__bridge id<MTLTexture>)(pairedColor->mtl_data)
                        : nil;
                    if (!pairedColorIsCurrentDrawTarget && pairedMTL) {
                        pairedColorIsCurrentDrawTarget =
                            mglRenderPassUsesColorTexture(_renderPassDescriptor,
                                                          pairedMTL,
                                                          &currentAttachmentIndex);
                    }
                }

                if (pairedColorIsCurrentDrawTarget) {
                    static uint64_t s_inSamplerDepthHistoryScanSuppressedLogCount = 0;
                    uint64_t hit = ++s_inSamplerDepthHistoryScanSuppressedLogCount;
                    if (hit <= 64ull || (hit % 512ull) == 0ull) {
                        NSLog(@"MGL INSAMPLER DEPTH HISTORY SCAN SUPPRESSED hit=%llu program=%u binding=%u unit=%u fbo=%u colorAttachment=%lu depthTex=%u pairedColor=%u currentDrawTarget=1",
                              (unsigned long long)hit,
                              (unsigned)fragmentProgramName,
                              (unsigned)spirvBinding,
                              (unsigned)textureUnit,
                              (unsigned)pairedFboName,
                              (unsigned long)currentAttachmentIndex,
                              ptr ? (unsigned)ptr->name : 0u,
                              pairedColor ? (unsigned)pairedColor->name : 0u);
                    }

                    id<MTLTexture> pairedCopy = nil;
                    BOOL usedPreviousVersion = NO;
                    if (pairedColor &&
                        mglRendererGLSampledCopyLooksUsable(pairedColor,
                                                            expectedType,
                                                            expectedKind,
                                                            YES,
                                                            &pairedCopy,
                                                            &usedPreviousVersion)) {
                        recoverTexture = pairedColor;
                        recoverMTL = pairedCopy;
                        recoverReason = "paired-current-copy";
                        recoveredFromSampledCopy = YES;
                        recoveredFromPreviousVersion = usedPreviousVersion;
                        recoverAttachmentIndex = currentAttachmentIndex;
                    } else {
                        static uint64_t s_inSamplerDepthCurrentTargetNoCopyLogCount = 0;
                        uint64_t noCopyHit = ++s_inSamplerDepthCurrentTargetNoCopyLogCount;
                        if (noCopyHit <= 64ull || (noCopyHit % 512ull) == 0ull) {
                            NSLog(@"MGL INSAMPLER DEPTH CURRENT TARGET NO COPY hit=%llu program=%u binding=%u unit=%u fbo=%u colorAttachment=%lu depthTex=%u colorTex=%u depthFmt=%lu sampledVersion=%u rtVersion=%u",
                                  (unsigned long long)noCopyHit,
                                  (unsigned)fragmentProgramName,
                                  (unsigned)spirvBinding,
                                  (unsigned)textureUnit,
                                  (unsigned)pairedFboName,
                                  (unsigned long)currentAttachmentIndex,
                                  ptr ? (unsigned)ptr->name : 0u,
                                  pairedColor ? (unsigned)pairedColor->name : 0u,
                                  (unsigned long)texture.pixelFormat,
                                  pairedColor ? (unsigned)pairedColor->mtl_gl_sampled_write_version : 0u,
                                  pairedColor ? (unsigned)pairedColor->mtl_render_target_write_version : 0u);
                        }
                        texture = nil;
                        suppressMissingTextureFallback = YES;
                    }
                } else if (pairedColor &&
                           pairedMTL &&
                           !mglMetalPixelFormatIsDepthOrStencil(pairedMTL.pixelFormat)) {
                    static uint64_t s_inSamplerDepthRecoveryLogCount = 0;
                    uint64_t hit = ++s_inSamplerDepthRecoveryLogCount;
                    if (hit <= 64ull || (hit % 512ull) == 0ull) {
                        NSLog(@"MGL INSAMPLER DEPTH RECOVERY hit=%llu program=%u binding=%u unit=%u fbo=%u depthTex=%u colorTex=%u depthFmt=%lu colorFmt=%lu size=%lux%lu",
                              (unsigned long long)hit,
                              (unsigned)fragmentProgramName,
                              (unsigned)spirvBinding,
                              (unsigned)textureUnit,
                              (unsigned)pairedFboName,
                              ptr ? (unsigned)ptr->name : 0u,
                              (unsigned)pairedColor->name,
                              (unsigned long)texture.pixelFormat,
                              (unsigned long)pairedMTL.pixelFormat,
                              (unsigned long)pairedMTL.width,
                              (unsigned long)pairedMTL.height);
                    }
                    ptr = pairedColor;
                    texture = pairedMTL;
                } else if (textureUnit < TEXTURE_UNITS) {
                    for (GLuint historyIndex = 0;
                         historyIndex < MGL_RECENT_SAMPLED_2D_HISTORY;
                         historyIndex++) {
                        Texture *candidate =
                            STATE(recent_sampled_2d_textures[textureUnit][historyIndex]);
                        if (!candidate ||
                            candidate == ptr ||
                            candidate == pairedColor ||
                            !mglRendererTextureLooksLikeSampledColor2D(ctx, candidate)) {
                            continue;
                        }

                        id<MTLTexture> candidateMTL = candidate->mtl_data
                            ? (__bridge id<MTLTexture>)(candidate->mtl_data)
                            : nil;
                        NSUInteger candidateAttachmentIndex = MAX_COLOR_ATTACHMENTS;
                        BOOL candidateIsCurrentDrawTarget =
                            mglCurrentDrawFramebufferUsesColorTexture(ctx,
                                                                      candidate,
                                                                      0u,
                                                                      &candidateAttachmentIndex) ||
                            mglRenderPassUsesColorTexture(_renderPassDescriptor,
                                                          candidateMTL,
                                                          &candidateAttachmentIndex);

                        if (!candidateIsCurrentDrawTarget &&
                            (!candidate->mtl_data || candidate->dirty_bits)) {
                            RETURN_FALSE_ON_FAILURE([self bindMTLTexture:candidate]);
                            MGL_ABORT_TBIND_IF_ENCODER_CLOSED();
                            candidateMTL = candidate->mtl_data
                                ? (__bridge id<MTLTexture>)(candidate->mtl_data)
                                : nil;
                            candidateAttachmentIndex = MAX_COLOR_ATTACHMENTS;
                            candidateIsCurrentDrawTarget =
                                mglCurrentDrawFramebufferUsesColorTexture(ctx,
                                                                          candidate,
                                                                          0u,
                                                                          &candidateAttachmentIndex) ||
                                mglRenderPassUsesColorTexture(_renderPassDescriptor,
                                                              candidateMTL,
                                                              &candidateAttachmentIndex);
                        }

                        id<MTLTexture> candidateCopy = nil;
                        BOOL usedPreviousVersion = NO;
                        if (candidate->is_render_target &&
                            mglRendererGLSampledCopyLooksUsable(candidate,
                                                                expectedType,
                                                                expectedKind,
                                                                candidateIsCurrentDrawTarget,
                                                                &candidateCopy,
                                                                &usedPreviousVersion)) {
                            recoverTexture = candidate;
                            recoverMTL = candidateCopy;
                            recoverReason = candidateIsCurrentDrawTarget
                                ? "history-current-copy"
                                : "history-copy";
                            recoveredFromSampledCopy = YES;
                            recoveredFromPreviousVersion = usedPreviousVersion;
                            recoverAttachmentIndex = candidateAttachmentIndex;
                            break;
                        }

                        if (candidateIsCurrentDrawTarget) {
                            continue;
                        }
                        if (candidateMTL &&
                            !mglMetalPixelFormatIsDepthOrStencil(candidateMTL.pixelFormat) &&
                            (expectedType == 0 || candidateMTL.textureType == expectedType) &&
                            mglTexturePixelFormatCompatibleWithExpectedDataKind(candidateMTL.pixelFormat, expectedKind)) {
                            recoverTexture = candidate;
                            recoverMTL = candidateMTL;
                            recoverReason = "history-direct";
                            recoverAttachmentIndex = candidateAttachmentIndex;
                            break;
                        }
                    }
                } else if (!pairedColor) {
                    static uint64_t s_inSamplerDepthUnpairedLogCount = 0;
                    uint64_t hit = ++s_inSamplerDepthUnpairedLogCount;
                    if (hit <= 64ull || (hit % 512ull) == 0ull) {
                        NSLog(@"MGL INSAMPLER DEPTH UNPAIRED hit=%llu program=%u binding=%u unit=%u depthTex=%u fmt=%lu size=%lux%lu",
                              (unsigned long long)hit,
                              (unsigned)fragmentProgramName,
                              (unsigned)spirvBinding,
                              (unsigned)textureUnit,
                              ptr ? (unsigned)ptr->name : 0u,
                              (unsigned long)texture.pixelFormat,
                              (unsigned long)texture.width,
                              (unsigned long)texture.height);
                    }
                }

                if (recoverTexture && recoverMTL) {
                    static uint64_t s_inSamplerDepthHistoryRecoveryLogCount = 0;
                    uint64_t hit = ++s_inSamplerDepthHistoryRecoveryLogCount;
                    if (hit <= 64ull || (hit % 512ull) == 0ull) {
                        NSLog(@"MGL INSAMPLER DEPTH RECOVERY hit=%llu reason=%s program=%u binding=%u unit=%u fbo=%u colorAttachment=%lu depthTex=%u recoverTex=%u depthFmt=%lu recoverFmt=%lu size=%lux%lu copy=%d prevVersion=%d sampledVersion=%u rtVersion=%u pairedColor=%u pairedCurrent=%d",
                              (unsigned long long)hit,
                              recoverReason,
                              (unsigned)fragmentProgramName,
                              (unsigned)spirvBinding,
                              (unsigned)textureUnit,
                              (unsigned)pairedFboName,
                              (unsigned long)recoverAttachmentIndex,
                              ptr ? (unsigned)ptr->name : 0u,
                              recoverTexture ? (unsigned)recoverTexture->name : 0u,
                              (unsigned long)texture.pixelFormat,
                              (unsigned long)recoverMTL.pixelFormat,
                              (unsigned long)recoverMTL.width,
                              (unsigned long)recoverMTL.height,
                              recoveredFromSampledCopy ? 1 : 0,
                              recoveredFromPreviousVersion ? 1 : 0,
                              recoverTexture ? (unsigned)recoverTexture->mtl_gl_sampled_write_version : 0u,
                              recoverTexture ? (unsigned)recoverTexture->mtl_render_target_write_version : 0u,
                              pairedColor ? (unsigned)pairedColor->name : 0u,
                              pairedColorIsCurrentDrawTarget ? 1 : 0);
                    }
                    ptr = recoverTexture;
                    texture = recoverMTL;
                }
            }
            TextureLevel *depthSampleLevel0 = mglTraceTextureBaseLevel(ptr);
            if (texture &&
                !sampledNameIsInSampler &&
                ptr &&
                ptr->is_render_target &&
                mglMetalPixelFormatIsDepthOrStencil(texture.pixelFormat) &&
                (!depthSampleLevel0 ||
                 !depthSampleLevel0->ever_written ||
                 !depthSampleLevel0->has_initialized_data)) {
                Texture *unitActive = textureUnit < TEXTURE_UNITS ? STATE(active_textures[textureUnit]) : NULL;
                Texture *unit2D = textureUnit < TEXTURE_UNITS ? STATE(texture_units[textureUnit].textures[_TEXTURE_2D]) : NULL;
                Texture *last2D = textureUnit < TEXTURE_UNITS ? STATE(last_sampled_2d_textures[textureUnit]) : NULL;
                Texture *recoverTexture = NULL;
                const char *recoverReason = "none";
                GLuint recoverFboName = 0u;

                Texture *pairedColor =
                    mglFindFramebufferColorTexturePairedWithDepth(ctx, ptr, &recoverFboName);
                if (pairedColor) {
                    RETURN_FALSE_ON_FAILURE([self bindMTLTexture:pairedColor]);
                    MGL_ABORT_TBIND_IF_ENCODER_CLOSED();
                    id<MTLTexture> pairedMTL = pairedColor->mtl_data
                        ? (__bridge id<MTLTexture>)(pairedColor->mtl_data)
                        : nil;
                    NSUInteger drawAttachmentIndex = MAX_COLOR_ATTACHMENTS;
                    BOOL pairedColorIsCurrentDrawTarget =
                        mglRenderPassUsesColorTexture(_renderPassDescriptor,
                                                      pairedMTL,
                                                      &drawAttachmentIndex);
                    if (pairedMTL &&
                        !pairedColorIsCurrentDrawTarget &&
                        !mglMetalPixelFormatIsDepthOrStencil(pairedMTL.pixelFormat) &&
                        (expectedType == 0 || pairedMTL.textureType == expectedType) &&
                        mglTexturePixelFormatCompatibleWithExpectedDataKind(pairedMTL.pixelFormat, expectedKind)) {
