        {
            if ((NSUInteger)i > (NSUIntegerMax - baseOffset) / commandStride) {
                NSLog(@"MGL WARNING: multiDrawElementsIndirect GL_QUADS command offset overflow draw=%d stride=%lu",
                      i,
